/* KOMU news: imported from komu.edu.ng (October 2026), newest first.
   To publish a story, add an entry at the top of this list. */
const NEWS=[{"id":119,"cat":"Admissions","date":"2026-09-01","title":"2026/2027 Supplementary Post-UTME and Direct Entry screening exercise","by":"John Maduabuchi Agomoh","img":"activities/May2026/01KSZCG3NYQ2Z2ZHVYJPVYPME8.png","sum":"Registration for the supplementary screening began on Tuesday 1 September 2026. Candidates who chose KOMU first in the 2026 UTME and scored 150 or above are invited to register, as are eligible Direct Entry candidates.","body":[["p","This is to inform the general public and eligible candidates that Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State, will commence registration for the 2026/2027 Supplementary Post-UTME and Direct Entry Screening Exercise on Tuesday, 1 September 2026."],["p","Candidates who chose KOMU as their institution of first choice in the 2026 Unified Tertiary Matriculation Examination (UTME) and scored 150 or above are invited to register for the Supplementary Screening Exercise. Eligible Direct Entry (DE) candidates are also invited to apply."],["p","UTME candidates who did not originally select KOMU as their institution of first choice but scored a minimum of 150 are also eligible to apply for admission into the available programmes, provided they effect a change of institution to KOMU on the JAMB portal."]]},{"id":118,"cat":"Leadership","date":"2026-08-26","title":"KOMU’s second substantive Vice-Chancellor, Prof. Frances Chukwukere, assumes office","by":"Obinna I Anyanwu","img":"activities/August2026/01M0YYEGW3WJZPZBS6XR3FTB0V.png","sum":"Prof. Frances Ngozi Chukwukere took over the administration of the University on Tuesday 25 August 2026, at a handover ceremony at the Liaison Office in Owerri.","body":[["p","HANDOVER: KOMU's 2nd Substantive VC, Prof. Chukwukere, Assumes Office"],["li","Commends Gov. Uzodimma for Appointment"],["li","Calls for Management, Staff Support"],["p","The newly appointed 2nd Substantive Vice-Chancellor of Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State, Professor Frances Ngozi Chukwukere, assumed office on Tuesday, August 25, 2026."],["p","The special ceremony, which took place at the University's Liaison Office, Owerri, featured the official handover of the University's administration to the new Vice-Chancellor."],["p","Handing over, the Deputy Vice-Chancellor (DVC), Professor Jude-Anthony Ogbulie, who oversaw the affairs of the University for three months, outlined his achievements in office and wished the new Vice-Chancellor well."],["p","Taking over, Prof. Chukwukere expressed gratitude to His Excellency, Senator Hope Uzodimma, Governor of Imo State, for appointing her Vice-Chancellor of the University, and pledged her loyalty."],["p","She thanked the DVC, as well as the Management and Staff of the University, for the warm reception accorded her, and assured them of an inclusive administration. She urged the institution's staff to reside within and around the University community for effective and efficient service delivery."],["p","The Vice-Chancellor further appealed to the University's stakeholders to support her administration, assuring them of her determination to lift the institution to greater heights."],["p","Prof. Chukwukere is an accomplished academic and author, with extensive University teaching and administrative experience. She is renowned for her work in indigenous knowledge, health-related advocacy and language preservation. She was recently among the specialised academics appointed by Ohanaeze Ndigbo to help revive and strengthen the Igbo language."],["p","The event, which was marked by a warm expression of love and acceptance of the new Vice-Chancellor, was witnessed by the expanded management of the University, including the Principal Officers, Faculty Deans, Directors, Heads of Departments, Unit Heads, Special Duty Staff, and friends from Imo University, Owerri."],["p","By Bright OKEREKE SA to the VC (Media)"]]},{"id":116,"cat":"Admissions","date":"2026-05-31","title":"2026/2027 Post-UTME and Direct Entry screening exercise","by":"","img":"gallery-photos/01KSZCCW5GTYFRKS7Q5HFE5NYH.jpeg","sum":"Registration ran from Monday 1 June to Friday 31 July 2026. Screening is based on verified UTME scores and O’Level results uploaded on JAMB CAPS.","body":[["p","This is to inform the general public and eligible candidates that Kingsley Ozumba Mbadiwe University will commence registration for the 2026/2027 Post-UTME and Direct Entry (DE) Screening Exercise on Monday, 1st June 2026."],["p","Candidates who chose KOMU as their First Choice Institution in the 2026 UTME or applied through Direct Entry are hereby invited to register for the Screening Exercise."],["p","The following conditions apply:"],["p","1. APPLICATION PERIOD"],["li","Application Opens: Monday, 1st June, 2026"],["li","Application Closes: Friday, 31st July, 2026"],["p","2. ELIGIBILITY CRITERIA"],["p","A. PROGRAMMES RESTRICTED TO FIRST-CHOICE CANDIDATES ONLY"],["p","Only candidates who selected KOMU as their First Choice Institution during the 2026 UTME registration are eligible to apply for admission into the following programmes:"],["li","Medicine and Surgery"],["li","Nursing Science"],["li","Law"],["li","Medical Laboratory Science"],["p","NOTE: Candidates who changed to KOMU as First Choice after the UTME registration will NOT be considered for admission into the above programmes."],["p","B. ALL OTHER PROGRAMMES"],["p","Candidates who did not originally choose KOMU as their First Choice Institution during the 2026 UTME but scored a minimum of 150 and above are eligible to apply for admission into other programmes, provided they effect a change of institution to KOMU on the JAMB CAPS portal."],["p","Admission into each programme shall be subject to meeting the minimum JAMB score requirement specified for that programme."],["p","3. MINIMUM JAMB SCORE REQUIREMENTS BY PROGRAMME"],["p","PROGRAMMES REQUIRING A MINIMUM JAMB SCORE OF 150"],["p","FACULTY OF ARTS"],["li","English and Literary Studies"],["li","History and Diplomatic Studies"],["li","Linguistics"],["li","Philosophy"],["p","FACULTY OF ALLIED HEALTH SCIENCES"],["li","Environmental Health Science"],["li","Public Health Science"],["p","FACULTY OF COMPUTING"],["li","Computer Science"],["li","Cyber Security"],["li","Information Technology"],["p","FACULTY OF ENVIRONMENTAL SCIENCES"],["li","Architecture"],["li","Estate Management"],["p","FACULTY OF SCIENCE"],["li","Animal and Environmental Biology"],["li","Biochemistry"],["li","Biology"],["li","Chemistry"],["li","Mathematics"],["li","Microbiology"],["li","Plant Science and Biotechnology"],["li","Physics"],["li","Statistics"],["p","FACULTY OF MANAGEMENT SCIENCES"],["li","Accounting"],["li","Finance"],["li","Business Administration"],["li","Entrepreneurship"],["li","Employment Relations & Human Resource Management"],["li","Marketing"],["p","FACULTY OF SOCIAL SCIENCES"],["li","Economics"],["li","Political Science"],["li","Psychology"],["li","Sociology"],["p","PROGRAMME REQUIRING A MINIMUM JAMB SCORE OF 200"],["p","PROGRAMMES REQUIRING A MINIMUM JAMB SCORE OF 210"],["p","PROGRAMME REQUIRING A MINIMUM JAMB SCORE OF 220"],["p","4. DIRECT ENTRY (DE) REQUIREMENTS"],["p","Direct Entry candidates must possess OND, HND, First Degree, or A’ Level qualifications in relevant disciplines, in addition to the compulsory five (5) credit passes in relevant O’Level subjects obtained at not more than two sittings."],["p","5. NATURE OF THE SCREENING EXERCISE"],["p","The 2026/2027 Post-UTME and Direct Entry Screening Exercise shall be based on verified JAMB scores and O’Level results (WAEC, NECO, GCE, or NABTEB) uploaded on the JAMB Central Admissions Processing System (CAPS)."],["p","6. IMPORTANT NOTICES"],["p","a. Candidates should ensure that the details on their JAMB CAPS correspond with the information provided on the Post-UTME application portal (e.g., JAMB Registration Number, Name, Date of Birth, State of Origin, etc.)."],["p","b. Candidates must use valid mobile phone numbers and e-mail addresses for communication."],["p","c. Candidates are required to upload their O’Level results on JAMB CAPS."],["p","d. ONLY candidates who successfully complete and submit their applications online shall be considered for admission."],["p","7. MODE OF PAYMENT AND REGISTRATION PROCEDURE"],["p","Eligible candidates are required to pay a non-refundable processing fee of ₦2,000.00 (Two Thousand Naira) only."],["p","ONLINE REGISTRATION STEPS"],["p","1. Visit the University website: www.komu.edu.ng"],["p","Alternatively, under the “Online Application” section, click “Post-UTME Screening Form.”"],["p","4. Click on “Start Your Admission Process.”"],["p","5. Click on “Start Application Process.”"],["p","6. Fill out the application form completely and correctly."],["p","7. Click “Submit.”"],["p","8. You will be directed to pay the Post-UTME/Direct Entry application fee of ₦2,000.00 only."],["p","9. On the Remita portal, an interface displaying your Name, Phone Number, E-mail Address, Reference Number (RRR), and Amount Payable will appear. If the details are correct, click “Submit.”"],["p","10. Remita supports several payment channels including card payment, bank transfer, USSD, bank invoice, Remita wallet, and phone number payment. Select your preferred payment method and follow the prompts to complete payment."],["p","8. PRINTING OF ACKNOWLEDGEMENT SLIP"],["p","To print your acknowledgement slip:"],["p","1. Visit: KOMU Continue Previous Application Portal"],["p","2. Enter your Application Number."],["p","3. Click on “Continue Application Process.”"],["p","4. When Printing, enable Background graphics on the Print page so that your passports will be visible. Print and bring your acknowledgement slip to the University on the screening day."],["p","9. IF YOU FORGOT YOUR APPLICATION NUMBER"],["p","Applicants who have forgotten their Application Number can retrieve their acknowledgement slip by following these steps:"],["p","2. Click on “Online Application.”"],["p","3. Click on “Post-UTME Screening Form” and read the instructions carefully."],["p","5. Click on “Continue Previous Admission Process.”"],["p","6. Enter your JAMB Registration Number."],["p","7. Click on “Continue Application Process.”"],["p","10. SUPPORT/ENQUIRIES"],["p","E-mail: [email protected]"],["p","Hotlines: 08175382217 08060722027 07034918110"],["p","Signed:"],["p","Dr. Rejoice N. Adioha Registrar"],["p","Top of Form"]]},{"id":114,"cat":"Leadership","date":"2026-04-24","title":"Prof. Ikechukwu N. S. Dozie emerges 9th Vice-Chancellor of FUTO","by":"","img":"activities/April2026/01KPZ1AAHHN0Y8VDJYBQPMZ4MM.jpeg","sum":"Prof. Dozie, who served as Vice-Chancellor of KOMU, was named the 9th substantive Vice-Chancellor of the Federal University of Technology, Owerri on Thursday 23 April 2026.","body":[["p","By Bright OKEREKE"],["p","The emergence of Professor Ikechukwu Nosike Simplicius Dozie, yesterday, Thursday April 23, 2026, as the 9th substantive Vice Chancellor of Federal University of Technology, Owerri (FUTO), is a clear fulfilment of God's promise of His glorious crown upon those who raced to perfection in Psalm 126:1 , thus; \"When the Lord turned again the captivity of Zion, we were like them that dream. Then was our mouth filled with laughter, and our tongue with singing: then said they among the heathen, The Lord hath done great things for them. The Lord hath done great things for us; whereof we are glad.\""],["p","Many have attested to Professor Dozie's new appointment, which has triggered streams of joy among stakeholders as divinity's reward for his diligence, resilience and commitment to true service while holding forth as the pioneer Vice Chancellor of Kingsley Ozumba Mbadiwe University (KOMU) Ideato Imo State, Nigeria,"],["p","Prof Dozie's new appointment which came-up 25 days to the end of his 5-year tenure as the pioneer Vice Chancellor of KOMU, has turned, days of subtle emotions occasioned by his winding-up tenure and final vacation of office into loud joy, realizing, he was merely appointed into a higher glory for a greater responsibility at the prestigious Federal University of Technology Owerri (FUTO)."],["p","Prof. I. N. S. Dozie, who will be leaving Kingsley Ozumba Mbadiwe University Ideato on May 18, 2026, will assume his new office as 9th substantive Vice Chancellor of the Federal University of Technology, Owerri (FUTO), on June 19, 2026."],["p","The renowned professor of Medical Microbiology and Parasitology, a Public Health Scientist, will replace Prof. Nnenna Oti, who will serve out her 5-year tenure on the 18th June, 2026."],["p","Professor Dozie, who has recorded an avalanche of laudable and modest legacies, is a great testimonial of what God can do for those who live, trust and stand on His promises."],["p","Believably! It is for Professor I.N.S. Dozie's sake; God made the promises in Isaiah 40:31 (KJV) manifest: \"But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.\" Hence, his rising grace of breaking greater grounds."],["p","Interestingly, an admixture of diligence, conscientiousness and divinity have enlisted Prof. I. N. S. Dozie, among the very few Nigerian Patriots who had the grace of serving 2 times as Vice Chancellors with much to be desired; the likes of Prof. Chimere Ikoku, Prof. Ango Abdullahi etc"],["p","Though Professor Dozie has served as a 2-time Dean at FUTO, before his appointment as the Vice Chancellor of KOMU, yet his return as the 9th Vice Chancellor, will indeed sign FUTO into the atmosphere of more innovative, robust and resourceful leadership trends built around cutting edge technology."],["p","Professor Dozie's wealth of administration and leadership experience, positively changes accelerating to higher productivity gear and advances the improvement of institutional brands, having led Kingsley Ozumba Mbadiwe University, from the creche through the turf era that challenged its possibilities of becoming, to a viable and top ranking world-class status with an envious ranking and visibility."],["p","We are therefore, standing on the promises of God, shouting and singing,\"Glory to God in the highest!\""],["p","Thumbs up with Roof top cheers up!"],["p","Bright OKEREKE is SA /VC Media."]]},{"id":112,"cat":"Academics","date":"2026-01-20","title":"KOMU blazes the trail in blended learning","by":"Abundance Chiziterem Okoye","img":"activities/January2026/01KFWN00NYFV4TF6S82VTSM70Y.jpeg","sum":"On Monday 19 January 2026 the Directorate of General Studies linked the Student Cinema and the Senate Chambers into a single real-time online classroom.","body":[["p","IDEATO – On Monday, 19 January 2026, the Directorate of General Studies (DGS) at Kingsley Ozumba Mbadiwe University (KOMU) successfully executed its scheduled online classes. This achievement underscores the institution’s expanding capacity for blended learning and technology-driven pedagogy."],["p","Innovative Synchronized Learning Environment"],["p","To manage the large student population, the University utilized a synchronized teaching model, linking two major lecture venues—the Student Cinema and the Senate Chambers—into a single, real-time online environment. This setup ensured that all students, regardless of their physical location, received uniform instruction and academic resources simultaneously."],["p","Student Distribution by VenueThe exercise saw broad participation across various departments, strategically distributed to ensure a smooth flow of information."],["p","Academic Scope"],["p","The sessions covered a diverse range of General Studies and Entrepreneurship courses, including:"],["li","GST 111: Communication in English"],["li","KOMU-GST 113: Innovative Agriculture and Food Security I"],["li","KOMU-FRN 201: French Language"],["li","KOMU-GST 213: Leadership Skills and Development"],["li","ENT 211: Entrepreneurship and Innovation"],["li","EPS 311: Venture Creation"],["p","Leadership and Commendations"],["p","The Vice-Chancellor’s Office extends its commendation to the leadership of the Directorate of General Studies, specifically Dr. Nkechi Nwanekezie (Director) and Dr. Leonard Nwafor (Deputy Director), for their seamless coordination."],["p","Special appreciation is also due to:"],["li","Supervisors: Dr. Amadi, Mr. Charles Enyinnaya, and Mr. Sanctus Ifeanyi."],["li","Lead Lecturers: Dr. Gift Ihejirika, Dr. Ogechi Anyaogu, and Dr. Odom Kenneth."],["p","Special thanks to Professor Aloy Onyeka, former KOMU DVC, who pioneered this initiative. We have no doubts that he will continue the legacy at the University of Innovation, Science and Technology, Omuma (UISTO), Imo State where he now serves as the pioneer Vice-Chancellor. KOMU and UISTO, two emerging digital state universities in Imo State, will continue to collaborate and partner together in digital and innovative higher education in Imo State and beyond the shores of this country."],["p","\"This successful exercise reinforces KOMU’s commitment to innovative teaching, inclusive access to education, and the strategic use of ICT to enhance learning outcomes across all faculties.\""]]},{"id":111,"cat":"Leadership","date":"2025-11-29","title":"Former DVC Prof. Aloysius Onyeka appointed pioneer Vice-Chancellor of UISTO","by":"Ikechukwu Nosike Dozie","img":"activities/May2026/01KSZCW81XVHR7HYMV5KPC8NJD.jpg","sum":"KOMU’s immediate past Deputy Vice-Chancellor was appointed the first substantive Vice-Chancellor of the University of Innovation, Science and Technology, Omuma (UISTO).","body":[["p","Kingsley Ozumba Mbadiwe University (KOMU), Ideato, proudly announces the appointment of our immediate past Deputy Vice-Chancellor, Professor Aloysius Chijioke Onyeka, as the First Substantive Vice-Chancellor of the University of Innovation, Science and Technology, Omuma (UISTO), Imo State. His appointment, approved by His Excellency, Distinguished Senator (Dr.) Hope Uzodimma, the Executive Governor of Imo State, takes effect from November 26, 2025."],["p","Professor Onyeka, a distinguished scholar of statistics, seasoned administrator, and pioneer of digital innovation in Nigerian higher education, has served KOMU with exceptional dedication and transformative vision. Appointed as Deputy Vice-Chancellor of KOMU in 2021, he played a pivotal role in strengthening academic governance, advancing ICT-driven reforms, and mentoring a new generation of scholars."],["p","Earlier in 2025, Professor Onyeka was appointed Acting Vice-Chancellor of Alvan Ikoku Federal University of Education (AIFUE), Owerri, where he provided strategic leadership and ensured stability during a critical transition period."],["p","A trailblazer in educational technology and digital transformation, Professor Onyeka is widely celebrated for pioneering Computer-Based Testing (CBT) at the Federal University of Technology, Owerri (FUTO) in 2015, and for developing innovative academic management tools that continue to be used across Nigerian universities. His contributions to statistical research, software development, and human capital development span decades of impactful scholarship and leadership."],["p","Professor Onyeka’s new role as pioneer Vice-Chancellor of UISTO is a fitting recognition of his visionary leadership, deep commitment to excellence, and unwavering service to the advancement of higher education in Imo State and Nigeria at large."],["p","The Management, Senate, Staff, and Students of Kingsley Ozumba Mbadiwe University extend heartfelt congratulations to Professor Aloysius Chijioke Onyeka. We are confident that he will bring the same distinction, innovation, and integrity to UISTO that have defined his remarkable career."],["p","We wish him continued success as he leads UISTO toward becoming a beacon of innovation, scientific research, and transformative education."]]},{"id":110,"cat":"Admissions","date":"2025-10-27","title":"Update for All Freshers (Newly Admitted Students)","by":"","img":null,"sum":"We are pleased to inform you that the University Portal is now open for payments.","body":[["p","Payments"],["p","We are pleased to inform you that the University Portal is now open for payments."],["p","Fresh students can now proceed to make payments for School Fees, Acceptance Fee, Accommodation, and Basic Student Services (BSS) for the 2025/2026 Academic Year via the approved payment channels on the University Portal."],["p","Kindly log in to the University Portal to complete your transactions. For any inquiries or assistance, please contact the Admissions Office."],["p","Thank you for your cooperation."],["p","— Management Admissions To view your name on the JAMB Approved Admission List (Ongoing), Click here To view your name on KOMU Recommendation to JAMB: First List, Click here To view your name on KOMU Recommendation to JAMB: Second List, Click Here To view your name on the KOMU Recommendation to JAMB: Third List, Click here To view your name on the MOP UP Recommendation to JAMB: List, Click here IMPORTANT NOTICE:"],["p","All candidates who have been recommended for admission into the departments listed below are hereby directed to take the following actions without delay:"],["li","Select KOMU as First Choice Institution on the JAMB CAPS portal (if you have not already done so)."],["li","Change your course on JAMB CAPS to the one recommended for you, as indicated in the list below."],["li","Upload your O’Level results to JAMB CAPS."],["li","Due to the inability of the Council of Legal Education to conduct her professional advisory visit to the LL.B Law programme, candidates who chose Law are redistributed and recommended to other courses in the Faculties of Arts and Social Sciences."],["p","These steps are mandatory and must be taken on or before Tuesday, 28th October 2025 to enable the Admission Office to proceed with the final processing of your admission with JAMB."],["p","Failure to comply with any of the above instructions may result in forfeiture of your admission opportunity."],["p","It is important to note that admission into public universities in Nigeria will end on Friday, 31st October 2025 as agreed at the JAMB policy meeting of July 8, 2025."],["p","Signed: University Management"]]},{"id":109,"cat":"Academics","date":"2025-09-24","title":"K. O Mbadiwe JUPEB Foundation School","by":"","img":null,"sum":"i. Navigating Your Academic Path with JUPEB: Expectations, Resources and Success Strategies","body":[["p","2025 ORIENTATION PROGRAMME FOR FRESH STUDENTS"],["p","Date: Thursday, September 25, 2025"],["p","Venue: The Senate Building"],["p","Time: 11 am"],["p","Theme: Scholarship and True Citizenship: Setting the Right Foundation"],["p","Activities"],["p","1. Opening Prayer"],["p","2. National Anthem"],["p","3. KOMU Anthem"],["p","4. General Introductions"],["p","a. University Principal Officers"],["p","b. JUPEB Officers and Staff"],["p","c. JUPEB Tutors"],["p","d. 2025/2026 Admission Set Students"],["p","5. Welcome Address - Programme Director"],["p","6. Opening Remarks – The Vice Chancellor"],["p","7. Lectures"],["p","i. Navigating Your Academic Path with JUPEB: Expectations, Resources and Success Strategies"],["p","ii. Campus Relationships and Student Life: Building Healthy Community Interactions"],["p","iii. Beyond the Gates: Respectful Engagements with Host Communities"],["p","iv. Focusing on the Goal: Embracing Academic Excellence and Integrity"],["p","8. Questions and Answers"],["p","9. Closing Remarks/Vote of Thanks"],["p","10. Closing Prayers"],["p","11. Group Photograph"],["p","12. A Tour of University Facilities"],["p","13. Allocation of Accommodation Signed"],["p","Dr Ndom Daniel"],["p","Director Of JUPEB"]]},{"id":108,"cat":"Admissions","date":"2025-09-09","title":"Second Admission List","by":"Abundance Chiziterem Okoye","img":null,"sum":"Please be informed that the payment of School Fees, Acceptance Fee, Accommodation, and other essential charges for the 2025/2026 Academic Year for fresh students will officially commence in the first week of November.","body":[["p","Please be informed that the payment of School Fees, Acceptance Fee, Accommodation, and other essential charges for the 2025/2026 Academic Year for fresh students will officially commence in the first week of November."],["p","Kindly note that all payment channels are temporarily disabled at the moment. Students are advised to check the University Portal regularly for updates or contact the Admissions Office for further assistance."],["p","Thank you for your understanding and cooperation."],["p","— Management"]]},{"id":106,"cat":"Leadership","date":"2025-08-31","title":"KOMU VC Professor I.N.S Dozie decorates in Pan-Africanism attire","by":"","img":null,"sum":"KOMU VC Professor I.N.S Dozie decorates in Pan-Africanism attire, receives Pan-African Honors and Kwame Nkruma Leadership Prize for Excellence from African Youth Council Delegation who arrived the University Campus on…","body":[["p","KOMU VC Professor I.N.S Dozie decorates in Pan-Africanism attire, receives Pan-African Honors and Kwame Nkruma Leadership Prize for Excellence from African Youth Council Delegation who arrived the University Campus on Tuesday August 5, 2025 from across Africa."]]},{"id":107,"cat":"Admissions","date":"2025-08-29","title":"2025/2026 UTME Merit Admission List Is Out!!","by":"","img":null,"sum":"CLICK HERE TO VIEW YOUR NAME ON THE MERIT LIST Missed Merit Admission? Don't worry! Click here to read our Supplementary Admission Application Guidelines and Procedure. Click here to fill out our Supplementary Form.","body":[["p","CLICK HERE TO VIEW YOUR NAME ON THE MERIT LIST Missed Merit Admission? Don't worry! Click here to read our Supplementary Admission Application Guidelines and Procedure. Click here to fill out our Supplementary Form."]]},{"id":104,"cat":"Admissions","date":"2025-07-17","title":"Advertisement for the 2025/2026 KOMU Post-UTME Screening Exercise","by":"Obinna I Anyanwu","img":null,"sum":"KOMU invites candidates with UTME scores of 150 and above, who desire admission into its NUC-approved undergraduate academic programmes for the 2025/2026 academic session, from Monday, 21st, July, 2025.","body":[["p","KOMU invites candidates with UTME scores of 150 and above, who desire admission into its NUC-approved undergraduate academic programmes for the 2025/2026 academic session, from Monday, 21st, July, 2025."]]},{"id":102,"cat":"Academics","date":"2025-07-01","title":"K.O. Mbadiwe University Elevates Academic Excellence with Full Accreditation of Two More Programmes","by":"Ikechukwu Nosike Dozie","img":null,"sum":"Kingsley Ozumba (K.O.) Mbadiwe University in Ideato, Imo State, continues to set a high standard for quality education, achieving a perfect score in the 2024 October/November accreditation exercise conducted by the…","body":[["p","Kingsley Ozumba (K.O.) Mbadiwe University in Ideato, Imo State, continues to set a high standard for quality education, achieving a perfect score in the 2024 October/November accreditation exercise conducted by the National Universities Commission (NUC). In a formal communication dated April 30, 2025, Engr. Abraham Chundusu, Acting Director of Accreditation, confirmed that the university secured full accreditation for its B.Sc. Architecture and B.Sc. Mathematics programmes. This milestone brings the total number of fully accredited programmes at the university to 17, reinforcing its commitment to academic rigor and excellence."],["p","The fully accredited programmes span multiple faculties, showcasing the university’s diverse academic offerings. In the Faculty of Science, students can pursue B.Sc. degrees in Microbiology, Biochemistry, Computer Science, Physics, and Animal & Environmental Biology. The Faculty of Social & Management Sciences offers B.Sc. programmes in Accounting, Finance & Banking, Business Administration, Economics, Sociology, Psychology, and Political Science. Meanwhile, the Faculty of Arts provides B.A. degrees in English & Literary Studies, History & International Relations, and Linguistics. This comprehensive portfolio reflects the university’s dedication to equipping students with knowledge and skills for global competitiveness."],["p","Professor I.N.S. Dozie, the Vice-Chancellor, expressed profound gratitude for this achievement, crediting divine guidance, the unwavering support of Governor Senator Hope Uzodimma, and the hard work of the university’s staff and students. He highlighted the Governor’s generous contributions during the accreditation preparations, which were instrumental in securing this success. Professor Dozie also praised the university community for their diligence and commitment, which have positioned K.O. Mbadiwe University as a beacon of educational excellence."],["p","Looking ahead, the university is preparing to present four additional programmes for the 2025 October/November accreditation exercise: B.Sc. Marketing, B.Sc. Entrepreneurship, B.Sc. Industrial Relations & Personnel Management, and B.A. Philosophy. These additions underscore the institution’s forward-thinking approach to meeting the evolving needs of students and industries."],["p","Professor Dozie emphasized the university’s mission to become a top-choice destination for prospective students across Nigeria. This vision is supported by innovative educational strategies, including a stable academic calendar, timely graduation, prompt mobilization for the National Youth Service Corps (NYSC), and the issuance of degree certificates and transcripts upon graduation. The university also integrates cutting-edge technology into teaching and learning and offers a unique dual-certification model, where graduates receive both a degree and a skill-based certificate, enhancing their employability."],["p","K.O. Mbadiwe University’s relentless pursuit of excellence is transforming the educational landscape, fostering a culture of innovation, mentorship, and opportunity. As it continues to expand its accredited programmes and elevate its academic standards, the university is poised to shape the future of higher education in Nigeria, empowering students to thrive in a dynamic global society."]]},{"id":103,"cat":"Admissions","date":"2025-06-28","title":"K. O. Mbadiwe Varsity turns Admission Seekers Top Choice As Candidates Rush Centres For Change to KOMU","by":"","img":null,"sum":"Kingsley Ozumba (K.O) Mbadiwe, University Ideato, in Imo State, has reportedly turned University Admission Seekers beautiful bride, following the unprecedented rise in the number of 2024/2025 Joint Admissions and…","body":[["p","Kingsley Ozumba (K.O) Mbadiwe, University Ideato, in Imo State, has reportedly turned University Admission Seekers beautiful bride, following the unprecedented rise in the number of 2024/2025 Joint Admissions and Matriculation Board (JAMB), candidates changing from their previously intended University and/or courses of study to Kingsley Ozumba Mbadiwe University (KOMU), Ideato."],["p","\"The surge according to reports from an independent survey is both impressive and amazing,\" a University Don, said in a chat."],["p","Information from Grapevine, reveals that the Imo State government, JAMB and NUC stakeholders from the State have expressed delight and satisfaction over the impressive development."],["p","However, the momentous achievements thus far, recorded by the university is said to be responsible for the amazing surge in the number of JAMB candidates seeking to gain admission for undergraduate programmes into the University."],["p","The University which is fast becoming an educational Pilgrimage Centre of sort, in Southeast, Nigeria and Africa, is in tanderm with its design and mission of world class status."],["p","A random assessment visit by our correspondent to some major Computer Centres within the State, further confirmed the report, as Desk Officers and Computer Operators who had a chat with our correspondent also corroborated the development, \"... no day passes-by without having some JAMB candidates who come for Change of institution, to K. O Mbadiwe University\" an Operation staff in one of the Centres, said."],["p","Recall that, few weeks ago the National Universities Commission (NUC), had in satisfaction with the results of its Resource Verification Exercise team, conducted recently, the Commission approved eight (8) new programmes (Courses) including MBBS Medicine and Surgery, Law, Nursing, Public health, Cyber Security among others, designed to take-off with the upcoming 2024/2025 academic session."],["p","These newly approved programmes are in addition to numerous others that have secured NUC's accreditation in the past."],["p","The University has graduated three (3) sets, with its 3rd set already enrolled for NYSC Programme."],["p","The advantages of studying in K. O. Mbadiwe University includes among others uninterrupted academic calendar, serene and conducive study environment, dedicated management team, teaching and non-teaching staff, State-of-the-Art Laboratories and Library, Digital/e-learning education and facilities, zero tolerance for crime and 'Certificate on Graduation' system."],["p","The admixture of a resourceful Vice Chancellor, Professor Ikechukwu N. S. Dozie and the support of an educationally loving Governor and Visitor, His Excellency, Dist. Sen. Hope Uzodimma CON, made these giant strides possible in less than 4 years."]]},{"id":98,"cat":"Partnerships","date":"2025-04-01","title":"Google Certificate Programme","by":"","img":null,"sum":"","body":[["p","AUF_SCHOLARSHIP_LIST"]]},{"id":97,"cat":"Academics","date":"2025-02-27","title":"The 7th Matriculation Ceremony of K.O. Mbadiwe University Is Here","by":"","img":null,"sum":"The 7th Matriculation Ceremony, which admits regular undergraduate students into full membership of the university for the 2024/2025 academic session, will be held on Thursday, March 6, 2025.","body":[["p","The 7th Matriculation Ceremony, which admits regular undergraduate students into full membership of the university for the 2024/2025 academic session, will be held on Thursday, March 6, 2025."]]},{"id":95,"cat":"Leadership","date":"2025-02-12","title":"KOMU DVC, Prof. Aloy Onyeka, Appointed Acting VC of Alvan Ikoku Fed. Uni. of Edu","by":"Ikechukwu Nosike Dozie","img":null,"sum":"IDEATO, IMO STATE – February 7, 2025 – Kingsley Ozumba Mbadiwe University (KOMU) is proud to announce the appointment of its Deputy Vice-Chancellor, Professor Aloy Onyeka, as the Acting Vice-Chancellor of Alvan Ikoku…","body":[["p","IDEATO, IMO STATE – February 7, 2025 – Kingsley Ozumba Mbadiwe University (KOMU) is proud to announce the appointment of its Deputy Vice-Chancellor, Professor Aloy Onyeka, as the Acting Vice-Chancellor of Alvan Ikoku Federal University of Education, Owerri. The appointment, approved by the Honourable Minister of Education, Dr. Maruf Tunji Alausa, is effective from February 10, 2025, for a maximum period of six months."],["p","The Federal Ministry of Education announced the appointment in a press release dated February 6, 2025. Professor Onyeka's appointment is a testament to his exceptional leadership, administrative prowess, and dedication to the advancement of higher education in Nigeria. He served as the Deputy Vice-Chancellor of KOMU with distinction, playing a pivotal role in the university's growth and development."],["p","A Champion of Digital Transformation at KOMU"],["p","Until this recent appointment, Professor Onyeka was in charge of the implementation of the Vice-Chancellor, Professor Ikechukwu N.S. Dozie's vision for digital transformation at KOMU.. He spearheaded the university's digitization efforts, working tirelessly to mainstream ICT for efficient teaching, learning, and administration. His contributions include the development of user-friendly software for academic transcript preparation, results processing, and course re-validation, demonstrating his commitment to leveraging technology to enhance the student and staff experience."],["p","Professor Onyeka, before this appointment, served as a Chief Consultant at OWERRI CBT HI-TECH, a JAMB-approved CBT Centre. He is also the National Coordinator of Say Absolute No To Exam-Malpractice (SANTEM-NG)."],["p","An Accomplished Scholar and Administrator"],["p","Professor Onyeka is a highly respected scholar with a distinguished academic background. He holds a PhD in Statistics from the University of Ibadan and has made significant contributions to the fields of statistical computing, sampling theory, and survey methodology. He has supervised over 80 successful PhD theses and is a member of several prestigious professional bodies, including the International Statistical Institute (ISI) and the Royal Statistical Society (RSS)."],["p","Professor Onyeka's career has spanned various institutions, including the Federal University of Technology, Owerri (FUTO), where he served as Head of the Department of Statistics and Director of the ICT Centre, and Abia State University, Uturu. His commitment to education extends beyond the university level, as evidenced by his authorship of resource handbooks for secondary and tertiary students."],["p","KOMU's Well Wishes"],["p","The Vice-Chancellor, Professor Ikechukwu N.S. Dozie, and the entire Management of KOMU extend their warmest congratulations to Professor Onyeka on this well-deserved appointment. While we will greatly miss his presence and contributions at KOMU, we are confident that he will bring the same level of dedication, expertise, and vision to Alvan Ikoku Federal University of Education. We wish him the very best in his new endeavour and look forward to witnessing the positive impact he will undoubtedly make."],["p","This appointment reflects not only Professor Onyeka's personal achievements but also the high caliber of leadership fostered at Kingsley Ozumba Mbadiwe University. We are proud to see our members contribute to the broader Nigerian educational landscape."],["p","Signed:"],["p","SA to VC on Media"]]},{"id":94,"cat":"Partnerships","date":"2024-12-16","title":"TD Africa and Huawei launch an ICT Academy with KOMU","by":"Ikechukwu Nosike Dozie","img":"activities/May2026/01KSZDWBKV2XJCJT4T1T8STZDG.jpg","sum":"TD Africa and Huawei Technologies launched an ICT Academy in partnership with KOMU, making the University a certified global ICT trainer.","body":[["p","It was another record of a giant feat as two global ICT leaders, TD Africa and Huawei Technologies, in partnership with Kingsley Ozumba Mbadiwe University Ideato, on Friday, November 29, 2024, launched the establishment of a mega ICT Academy that is committed to driving ICT super skills and capacity building in Nigeria."],["p","The moment of the launch ecstatically electrified the exquisite Sam Mbakwe hall of the Rockview Hotels, Owerri, filled with staff and students of K. O. Mbadiwe University and many other guests, drawn from various walks of life, who graced the event."],["p","Strategic and prominent among the guests included the Commissioner for Digital Economy and E-Government, Dr. Chimezie Amadi, who represented the Imo State Governor and Visitor of the University, His Excellency, Distinguished Senator Hope Uzodimma CON, and the Tertiary Education Commissioner, Prof. Victor Nwachukwu, in representation."],["p","Both TD Africa and Huawei Technologies are known leading global providers of Information and Communications Technology (ICT) infrastructure and smart devices."],["p","The KOMU Vice-Chancellor, Professor I.N.S. Dozie, in his opening remarks, highlighted the unique achievements of the young but fast-growing university. He expressed his profound appreciation for TD Africa and Huawei Technologies for partnering with Kingsley Ozumba Mbadiwe University Ideato, for the wonderful initiative and further said, the ICT Academy, is in tandem with the University's vision of becoming one of the global leading ICT-based institutions."],["p","He praised the two global ICT companies for their contribution to technology innovation and advancement globally."],["p","Mrs. Chioma Chimere, the Coordinating Managing Director of TD Africa, in her speech, expressed enthusiasm for the ICT Academy; explained that TD Africa, one of the largest distributors of cutting-edge technology solutions in Nigeria, has strengthened their partnership to drive digital transformation in Africa."],["p","According to her, the ICT Academy is intended to deliver practical skills and training on emerging ICT developments with globally rated certifications."],["p","The TD Africa's Executive Director, Mezie Emelonye, in his testimonial speech, which dwelt on 'how the greatness of this day was made'; He pulled the mild, touchy but glowing tributary of three (3) K.O. Mbadiwe University students, pressured on him by Dr. Festus Eze, of KOMU, for Industrial Training (IT), who in turn made the University proud with excellent performances amidst desirous quest for more knowledge. \"It was this challenge and breakthrough that triggered the birth of this mega ICT Academy, being launched, today,\" he said. He further expressed TD Africa's commitment to the support and development of the Academy."],["p","In another remark, Mr. Gary Li, who led the Huawei team, emphasized that the training offers an internationally recognized certification which equips the students with global standard skills that qualify them for ICT jobs anywhere in the world."],["p","The Imo State Commissioner for Digital Economy, Dr. Chimezie Amadi, in his remarks; expressed satisfaction with the achievement of that mega ICT Academy in Imo State, especially, doing it, in partnership with two global ICT giants. He said the Academy further compliments the Imo Digital City under construction by the Governor of Imo State, His Excellency, Distinguished Senator Hope Uzodimma. The Commissioner's, who began his speech with background information of TD Africa, said, he is also confirmed, he is a product of Zinox Group. He eulogized the KOMU Vice-Chancellor for the mega attraction."],["p","The hallmark of the event was the unveiling of the all-in-one solution eKit's delivered to the Academy for robust connectivity, intelligent collaboration tools, and reliable storage, which includes: Routers, Switches, Access Points, and IdeaHub."],["p","While, the University Orator, Dr. C. P. Dozie, coordinated the program flow, the University Registrar, Dr. Juliet Ekwugha, gave the closing remarks. Bright Okereke"],["p","SA to the VC, on Media"]]},{"id":92,"cat":"Admissions","date":"2024-11-16","title":"KOMU Second Admission List Is Out!!","by":"","img":null,"sum":"Don't miss your chance to study at KOMU! Apply Now: [Link to Application Form] Deadline: Admission is ongoing","body":[["p","KOMU Post-UTME Application is Still Open!"],["p","Don't miss your chance to study at KOMU! Apply Now: [Link to Application Form] Deadline: Admission is ongoing"],["p","Interested in Public Health, Environmental Health, Cyber Security, or Information Technology? Also Fill out the Supplementary Form as well: [Link to Supplementary Form]"]]},{"id":91,"cat":"Admissions","date":"2024-11-16","title":"KOMU First Merit List","by":"Rejoice N. Adioha","img":null,"sum":"The University published its 2024/2025 UTME first merit list, naming admitted candidates under each programme.","body":[["p","The University published its 2024/2025 UTME first merit list, naming admitted candidates under each programme."],["p","Candidates can confirm their admission status on the admission list for their programme on the Admissions page."]]},{"id":64,"cat":"Admissions","date":"2024-10-10","title":"Advertisement for Supplementary Admissions into New Programmes","by":"","img":null,"sum":"Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State, announces the commencement of Supplementary Admissions for the 2024/2025 academic session into new programmes in the College of Medicine, Faculty of Allied…","body":[["p","Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State, announces the commencement of Supplementary Admissions for the 2024/2025 academic session into new programmes in the College of Medicine, Faculty of Allied Health Sciences, and Faculty of Science."],["p","Only applicants who completed the KOMU PUTME are eligible for Supplementary Admissions."],["p","Application commences on Monday, October 07, 2024."]]},{"id":63,"cat":"Admissions","date":"2024-10-09","title":"Supplementary Admissions","by":"","img":null,"sum":"This is to inform the public and interested candidates who were involved in the 2024 UTMEthat Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State will commence Supplementary Admissions into the under listed new…","body":[["p","KINGSLEY OZUMBA MBADIWE UNIVERSITY, IDEATO, IMO STATE"],["p","OFFICE OF THE REGISTRAR"],["p","(ADMISSIONS UNIT)"],["p","ADVERTISEMENT FOR SUPPLEMENTARY ADMISSIONS INTO NEW PROGRAMMES"],["p","This is to inform the public and interested candidates who were involved in the 2024 UTMEthat Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State will commence Supplementary Admissions into the under listed new programmes in the 2024/2025 Admissions Exercise."],["p","Below are the faculties, departments, UTME subject combinations, and the required minimum JAMB scores for each programme:"],["li","College of MedicineMedicine & Surgery: Candidates must have sat for Biology, Physics, and Chemistry in the UTME and scored a minimum of 200."],["li","Faculty of Allied Health SciencesNursing Science: UTME subject combination is Biology, Physics, and Chemistry. The minimum JAMB score is 200."],["li","Medical Laboratory Science: The required UTME subjects are Biology, Physics, and Chemistry, with a minimum JAMB score of 160."],["li","Public Health: The required subjects are Biology, Physics, and Chemistry, and the minimum JAMB score is 140."],["li","Environmental Health Science: Candidates must have taken Biology, Physics, and Chemistry, with a minimum JAMB score of 140."],["li","Faculty of ScienceInformation Technology: Candidates should have sat for Mathematics, Physics, and Chemistry in the UTME, with a minimum score of 140."],["li","Cybersecurity: The required UTME subjects are Mathematics, Physics, and Chemistry, with a minimum JAMB score of 140."],["p","The following conditions apply:"],["p","Application commences on Monday, October 07, 2024."],["p","All interested candidates who chose KOMU as First Choice University in the 2024 Unified Tertiary Matriculation Examination (UTME) and scored a minimum of the above specified JAMB scores can apply."],["p","UTME subject combination as indicated in the above tableis applicable in addition to possessing at least five (5) O’Level credit passes in Mathematics, English language, Chemistry, Physics and Biology in at most two sittings."],["p","Those who did not choose KOMU as first choice University but scored a minimum of the above specified JAMB minimum scores in the various programmes can also apply on the condition that they visit the JAMB website for a change of Institution to KOMU."],["p","Candidate must have uploaded their correct O’Level results on JAMB PORTAL."],["p","IMPORTANT NOTICE: Only those who have already applied for the mandatory KOMU PUTME will be eligible to apply for Supplementary admission into the new programmes!"],["p","Mode of Payment and Supplementary Registration Procedure"],["p","If you are yet to apply for 2024/2025 KOMU PUTME, kindly proceed as follows:"],["p","1. Visit the University website at www.komu.edu.ng"],["p","2. Click on \"Online Application\" and follow the prompts."],["p","3. Pay the post-UTME/Direct Entry application fee of ₦2,000."],["p","4. Print the Acknowledgement slip."],["p","Please, ignore the above four (4) steps if you had earlier applied for the current 2024/2025 KOMU PUTME."],["p","To apply for Supplementary admission into the new programmes (after applying for 2024/2025 KOMU PUTME), kindly proceed as follows:"],["li","Visit the University official website www.komu.edu.ng"],["li","Click on “Online Application”"],["li","Under Undergraduate Admission, click on Supplementary Application."],["li","Follow the prompts till you get to the page where you would be asked to enter your JAMB Reg. Number or your Admission Form Screening App Number"],["li","Enter your JAMB Registration Number and Click on “Continue”. Your details will display if you had earlier applied for 2024/2025 KOMU PUTME, otherwise, follow the above steps (1)-(4) to first apply for KOMU PUTME and return to step (i) above, thereafter."],["li","Complete and submit online the Supplementary Application Form."],["li","You will be directed to pay the Supplementary admission application fee of ₦10,000.00 (Ten Thousand Naira) Only."],["li","On the Remita Portal an interface will be displayed containing your Name, Phone Number, email, Reference number (RRR) and the amount you want to pay. If the details displayed are correct, click “Submit”."],["li","Remita offers several payment methods/channels, including card payment, bank transfer, USSD, bank invoice, Remita wallet, and phone number payment."],["li","Print out your “Supplementary Form Acknowledgement Slip”"],["p","For more information on the admission requirements and process, you can visit the KOMU website or contact the University directly on:"],["li","Phone: 08034646192, 08134435535"],["li","Email: [email protected] or"],["li","Admissions Office, KOMU."],["p","Signed:"],["p","Dr. Rejoice N. Adioha"],["p","University Admissions Officer"],["p","For: Registrar"]]},{"id":62,"cat":"Academics","date":"2024-09-15","title":"NUC Approves Eight New Programmes for KOMU, Including Medicine, Law & Nursing","by":"Aloysius Chijioke Onyeka","img":null,"sum":"The National Universities Commission (NUC) has considered and approved the establishment of the full-time mode of the following eight (8) new programmes to be run at Kingsley Ozumba Mbadiwe University (KOMU) with effect…","body":[["p","The National Universities Commission (NUC) has considered and approved the establishment of the full-time mode of the following eight (8) new programmes to be run at Kingsley Ozumba Mbadiwe University (KOMU) with effect from the 2024/2025 academic session."],["li","MBBS. Medicine"],["li","B.NSc. Nursing Science"],["li","B.MLS. Medical Laboratory Science"],["li","LL.B. Law"],["li","B.Sc. Information Technology"],["li","B.Sc. Cyber Security"],["li","B.Sc. Public Health"],["li","B.Sc. Environmental Health Science"],["p","Congratulations to His Excellency, the Executive Governor of Imo State and the Visitor to the University, Distinguished Senator Hope Uzodinma."],["p","Congratulations to our indomitable and visionary Vice-Chancellor, Professor Ikechukwu N.S. Dozie."],["p","Congratulations to KOMU Management team, KOMU staff, KOMU students, the good people of Imo State, and all KOMU friends and well-wishers."],["p","All roads now lead to KOMU, especially with the introduction of these eight (8) new programmes and all other giant strides of our Vice-Chancellor, Professor Ikechukwu N. S. Dozie, within a space of just three (3) years in office."],["p","To God be the glory!"],["p","Professor Aloy Onyeka"],["p","DVC, KOMU"],["p","12/09/2024"]]},{"id":61,"cat":"Academics","date":"2024-09-15","title":"Kingsley Ozumba Mbadiwe University Hosts 1st International Conference on Liberal Arts and Management Sciences","by":"","img":null,"sum":"Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State, will host its 1st International Conference on Liberal Arts and Management Sciences, scheduled to take place from November 20th to 23rd, 2024. The conference…","body":[["p","Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State, will host its 1st International Conference on Liberal Arts and Management Sciences, scheduled to take place from November 20th to 23rd, 2024. The conference is expected to attract scholars, practitioners, researchers postgraduate students from across the globe, with the theme, \"Fostering Sub-Saharan Africa Development through Interdisciplinary Collaborations: Liberal Arts and Management Sciences.\""],["p","The event will focus on addressing key business, economic, sociocultural developmental challenges facing Sub-Saharan Africa and how interdisciplinary approaches and collaboration across liberal arts and management sciences disciplines can foster sustainable solutions. Attendees will explore diverse sub-themes, including:"],["li","Political Economy and Governance"],["li","Social Justice and Human Rights"],["li","Cultural Diversity and Heritage"],["li","Business Innovation and Financial Stability"],["li","Climate Change and Environmental Sustainability"],["li","Artificial Intelligence and Financial Risk"],["li","Big Data and Business Analytics"],["li","Peace & Conflict Resolution"],["li","Entrepreneurship"],["li","And many others."],["p","The conference will officially open on November 21st, 2024, following arrival and registration on November 20th, 2024, with events concluding on November 23rd, 2024. The venue for the event is the Senate Building at Kingsley Ozumba Mbadiwe University."],["p","One of the event’s highlights will be the presence of His Excellency, Senator Hope Uzodinma, the Executive Governor of Imo State, who will serve as the Special Guest of Honour. The conference will also feature insightful keynote addresses by renowned academics and industry leaders, including Prof. A.C. Ezirim from the Department of Marketing, University of Port Harcourt, and Prof. Ngozi Egbuna, Director of the International Trade Research Centre, Nnamdi Azikiwe University Awka."],["p","Conference participation fees are set at N25,000 for paper presenters; N10,000 for attendants not presenting papers and postgraduate students; N5,000 for undergraduate students; and USD100 for international participants. Attendees are required to submit a 250-word abstract, following the APA 6th edition referencing style."],["p","Certificates will be issued to all participants."],["p","Participation will be Hybrid (Physical + Visual)"],["p","For more information, interested participants can contact the organizing committee via Phone numbers listed, 08033249200, 08034046780, 08060722027."],["p","The Kingsley Ozumba Mbadiwe University community eagerly anticipates this significant event and invites participants from various sectors to engage in meaningful dialogue and collaboration for the betterment of Sub-Saharan Africa. Signed:"],["p","Prof. O.T. Ebiringa"],["p","LOC CHAIRMAN"]]},{"id":60,"cat":"Admissions","date":"2024-08-05","title":"Admission Into the Undergraduate Academic Programmes Of K.O. Mbadiwe University (KOMU)","by":"Rejoice N. Adioha","img":null,"sum":"Candidates who chose Kingsley Ozumba Mbadiwe University as First Choice Institution in the 2024 Unified Tertiary Matriculation Examination (UTME) and Direct Entry (DE) are hereby invited to the Screening Exercise for…","body":[["p","ADVERTISEMENT FOR 2024/2025 KOMU POST-UTME AND DIRECT ENTRY SCREENING EXERCISE"],["p","Candidates who chose Kingsley Ozumba Mbadiwe University as First Choice Institution in the 2024 Unified Tertiary Matriculation Examination (UTME) and Direct Entry (DE) are hereby invited to the Screening Exercise for admissions. The following conditions apply:"],["li","Application commences on August 5, 2024 and closes on October 31, 2024. ONLY candidates that scored a minimum of 140 in their UTME are ELIGIBLE to apply."],["li","Candidates who did not select K.O. Mbadiwe University (KOMU) as their first choice in the JAMB-UTME but scored a minimum of 140 can apply to KOMU. However, they must change their institution of first choice to KOMU on the JAMB Central Admission Processing System (CAPS) to be considered for admission."],["li","The various Programmes are as follows:"],["p","A. FACULTY OF ARTS"],["li","English & Literary Studies (B.sc)"],["li","History & International Studies (B.sc)"],["li","Linguistics (B.sc)"],["li","Philosophy (B.sc)"],["p","B. FACULTY OF EVIRONMENTAL SCIENCES"],["li","Architecture (B.sc)"],["li","Estate Management (B.sc)"],["p","C. FACULTY OF SCIENCE"],["li","Animal & Environmental Biology (B.sc)"],["li","Biochemistry (B.sc)"],["li","Biology (B.sc)"],["li","Chemistry (B.sc)"],["li","Computer Science (B.sc)"],["li","Mathematics (B.sc)"],["li","Microbiology (B.sc)"],["li","Physics (B.sc)"],["li","Plant Science and Biotechnology (B.sc)"],["li","Statistics (B.sc)"],["p","E. FACULTY OF SOCIAL AND MANAGEMENT SCIENCES"],["li","Accounting (B.sc)"],["li","Banking & Finance (B.sc)"],["li","Business Administration (B.sc)"],["li","Economics (B.sc)"],["li","Entrepreneurship (B.sc)"],["li","Industrial Relations & Personal Management (B.sc)"],["li","Marketing (B.sc)"],["li","Political Science (B.sc)"],["li","Psychology (B.sc)"],["li","Sociology (B.sc)"],["p","Interested candidates who wish to apply to any of our new programmes listed below should first apply to any of the available programmes above before proceeding to the supplementary form. Click here to apply for supplementary admission"],["p","A. College of Medicine"],["li","Medicine & Surgery: Candidates must have sat for Biology, Physics, and Chemistry in the UTME and scored a minimum of 200."],["p","B. Faculty of Allied Health Sciences"],["li","Nursing Science: UTME subject combination is Biology, Physics, and Chemistry. The minimum JAMB score is 200."],["li","Medical Laboratory Science: The required UTME subjects are Biology, Physics, and Chemistry, with a minimum JAMB score of 160."],["li","Public Health: The required subjects are Biology, Physics, and Chemistry, and the minimum JAMB score is 140."],["li","Environmental Health Science: Candidates must have taken Biology, Physics, and Chemistry, with a minimum JAMB score of 140."],["p","Faculty of Science"],["li","Information Technology: Candidates should have sat for Mathematics, Physics, and Chemistry in the UTME, with a minimum score of 140."],["li","Cybersecurity: The required UTME subjects are Mathematics, Physics, and Chemistry, with a minimum JAMB score of 140."],["p","4. Mode of Payment and Registration Procedure:"],["p","Eligible candidates are required to pay a processing fee of ₦2,000.00 (Two Thousand Naira) only."],["p","To register, follow these steps:"],["li","Visit the University website www.komu.edu.ng"],["li","Click on “Online Application”"],["li","Click on “Apply online” and read the instructions"],["li","Click on “Start your Admission Process”"],["li","Click on “Start Application Process”"],["li","Fill out the form completely and correctly"],["li","Click on “Submit”"],["li","You will be directed to pay the post UTME/Direct Entry application fee of ₦2000 (Two Thousand Naira) Only."],["li","On the Remita Portal an interface will be displayed containing your Name, Phone Number, email, Reference number (RRR) and the amount you want to pay. If the details displayed are correct, click “Submit”."],["li","Remita offers several payment methods/channels, including card payment, bank transfer, USSD, bank invoice, Remita wallet, and phone number payment. Select your preferred method and follow the prompts to complete the payment."],["li","Print the Acknowledgement slip, which is also sent to your email."],["li","Bring your Acknowledgement slip to the University on the post-UTME screening day."],["p","How to get your Admission Acknowledgement Slip if you applied using an incorrect email on the KOMU Website"],["li","Click on “Continue Previous Admission Process”"],["li","Enter your application number"],["li","Click on \"Continue Application Process\""],["p","Alternatively, you can get your Admission Acknowledgement Slip in 3 simple steps from the KOMU website"],["li","Click on this link www.bit.ly/komu-continue-previous-application"],["p","5. BENEFITS OF STUDYING IN KOMU"],["li","Uninterrupted Study"],["li","Stable academic calendar"],["li","Timely Graduation"],["li","Certificate on Graduation"],["li","Transcript on demand"],["li","Affordable fees"],["p","HURRY NOW AND APPLY !!"],["p","For support contacts:"],["p","Call: 08034646192, 08134435535"],["p","Email: [email protected]"],["p","Signed: Dr. Rejoice N. Adioha (University Admission Officer) For: Registrar"]]},{"id":59,"cat":"Academics","date":"2024-07-01","title":"K. O. Mbadiwe University holds 3-day Entrepreneurship Development Workshop...As participants express satisfaction over programme impact","by":"Ikechukwu Nosike Dozie","img":null,"sum":"It was epoch-making as Kingsley Ozumba (K. O) Mbadiwe University, Ogboko in Ideato South Local Government Area of Imo State engaged the students and staff of the University on a 3-day Training Workshop aimed at…","body":[["p","It was epoch-making as Kingsley Ozumba (K. O) Mbadiwe University, Ogboko in Ideato South Local Government Area of Imo State engaged the students and staff of the University on a 3-day Training Workshop aimed at Entrepreneurship, Innovation and Job creation initiatives for emerging graduates of the Nigerian Universities."],["p","The programme which held from Tuesday June 25 to Thursday 27, 2024 at the University's Senate Building, from 2:00pm to 4:00Pm, for the three (3) days, allowed Online Participation for those who could not be present."],["p","The historic Workshop enjoyed the support and partnership of various well meaning Professional and Public Agencies who gave the programme a special touch of excellence."],["p","Furthermore, the presence and commendations of organisations like the Nigerians In Diaspora Organisation (NIDO) Europe, National Directorate of Employment (NDE), Small and Medium Enterprise Development Agency of Nigeria (SMEDAN), National Youth Council of Nigeria (NYCN), Nigerian Export Promotion Council (NEPC) and the great National Universities Commission (NUC) among many others."],["p","The double Certification Program, which is the first of its kind in South East and the second in Nigeria, has has further consolidated Kingsley Ozumba (K.O.) Mbadiwe University, (KOMU) at the global and international space."],["p","K. O. Mbadiwe University EDC (KOMU-EDC) in Collaborations with the University Innovation Training Centre (KOMU-ITC) were key operators towards making the programme possible."],["p","Obinna Wachukwu, who presented the goodwill message on behalf of the National Universities Commission (NUC), identified that the programme is aimed at helping the emerging new graduates start and develop their own businesses as an alternate means of achieving self-goal especially in a time like this when there are little or no job employment opportunities for graduates."],["p","The Vice Chancellor of the University, Professor I.N.S Dozie, in his remarks eulogised the Imo State Governor and Visitor of University, Distinguished Senator Hope Uzodimma (CON) for his unflinching support to the University and as well, the Commissioner for Education, Prof Johncliff Nwadike, who gave goodwill message on behalf of the Imo State Government. The VC, also applauded Obinna Wachukwu for his valuable remarks as conveyed in his goodwill message on behalf the NUC."],["p","The Vice Chancellor further appreciated the contributions of the University's Deputy Vice Chancellor (DVC), Prof Aloy Onyeka, the Programme Cordinator, Professor O. T. Ebiringa, and the entire institution's management staff for their efforts towards the programme a huge success."],["p","Others who were present at the programme includes Nzeocha Emmanuel of the National Directorate of Employment (NDE), Dr. Mrs. Ifeoma Onyia of Small and Medium Enterprises Development Agency of Nigeria (SMEDAN), Edili Agumage of the Nigeria Export Promotion Council (NEPC), Mrs Nwachukwu Theresa, Cordinator, National Directorate of Employment (NDE) Imo State, Staff and Students of K.O. Mbadiwe University, Ideato among many others."],["p","The Students' Union Government (SUG) President, on behalf of the students thanked the VC, the University management and the programme partners for the rare opportunity."],["p","Bright Okereke, is the SA/VC Media writes from KOMU!"]]},{"id":57,"cat":"Academics","date":"2024-03-09","title":"Call for Papers","by":"Ikechukwu Nosike Dozie","img":null,"sum":"KOMU Journal of Health and Environmental Research (KOJHER) is a multidisciplinary academic, peer-reviewed, and open access publication of Kingsley Ozumba Mbadiwe University(KOMU) Ideato-Imo State. The Kingsley Ozumba…","body":[["p","KOMU JOURNAL OF HEALTH AND ENVIRONMENTAL RESEARCH(KOJHER)Call for PapersKOMU_LOGO.jpg 42.13 KBABOUT THE JOURNAL"],["p","KOMU Journal of Health and Environmental Research (KOJHER) is a multidisciplinary academic, peer-reviewed, and open access publication of Kingsley Ozumba Mbadiwe University(KOMU) Ideato-Imo State. The Kingsley Ozumba Mbadiwe University (KOMU) is a public university owned by Imo State government. It is officially accredited and recognized by the National Universities Commission (NUC) in Nigeria. KOJHER publishes high-quality Health and Environmental Research articles two times a year. The journal is open for the academic world and research institutes, academic and professional libraries, graduate students and PhD candidates, academic and non-academic researchers and research teams. Our goal is to provide original, relevant, and timely information from a diversity of sources with immense integrity for the need of local and international scholars. Should your research help us achieve our goal, we shall be glad to have your manuscript. All manuscripts are subject to a double-blind review by the editorial board and other scholars who are noted experts in the appropriate subject area. Manuscripts are welcomed throughout the year but treated as first come, first served. We also welcome the publication of special issues and conference proceedings."],["p","Scope, Focusand Objectives"],["p","KOJHER approaches the thematic focus of health and environmental research from interdisciplinary perspectives. Our journal is interested to promote multidisciplinary research in the fields of health and environmental studies. The journal´s aim is to promote the exchange of scientific ideas and to bring together health researchers, scientists, technologist, environmentalists, academics and policymakers. KOJHER provides an international opportunity for research studies that seeks to promote original theoretical and empirical works including review papers in all spheres of health and environmental studies that advance and enhance the understanding of theory and practice. Specifically, the journal will provide the forum:"],["p","· For the dissemination of information and discussions on health and environmental issues that result from the findings of research."],["p","· That would encourage, coordinate, as well as facilitate the publication of findings from original research endeavors."],["p","· KOJHER would act as a public voice for researchers and scholars in the field of health and environmental studies alike; offering contributors the arena that enables unrestricting responses."],["p","Guidelines for Contributors"],["p","Manuscripts must conform to the following guidelines or otherwise such manuscripts may not be processed:"],["p","· Manuscripts should be typed in English along with an abstract of about 200 words. The abstract should spell out the aim of the paper and the summary of the work with not more than 5 keywords"],["p","· Manuscripts should bear a separate page for the title of the paper, name(s) and biographical information of the contributor(s) including their email addresses, name(s) and physical addresses of the institutions of affiliation."],["p","· Length of paper including tables, diagrams, illustrations etc should be between 4000 and 8000 words"],["p","· Manuscripts should be original and unpublished. We don’t encourage articles that is just copied and pasted from different websites, books or journals and assembled together."],["p","· All submissions to this journal will be property of the KOJHER. Copyright resides with Kingsley Ozumba Mbadiwe University(KOMU) Nigeria."],["p","· All articles must be in MS Words inTimes New Roman with front size 12"],["p","· Short communication to review articles, book reviews, reports of conferences, summary or views of government reports are published as space permit"],["p","· All non-English words should be in italics"],["p","· The language has to be properly checked. We prefer authors to use UK English."],["p","· All pages must be numbered appropriately. Footnotes and endnotes can be used where possible."],["p","· It’s necessary to provide references in the body of text."],["p","· Authors are responsible for the accuracy of the figures, quotations and references"],["p","· Bibliographical references should be arranged in alphabetically and should be given at the end of the text."],["p","· Authors must be informed that double submission is illegal where an article is submitted to two publishing journals at the same time."],["p","Manuscript Review Process"],["p","All articles will be submitted to referees. The consulting editors/referees will have documented expertise in the area the article addresses. When reviews are received, an editorial decision will be reached to either not accept the article, accept the article without revision, accept the article with revision not requiring reconsideration by referee, accept the article with revision requiring reconsideration by referee or accept as short report. The decision of Editorial Board is final."],["p","Page Charges"],["p","KOMU Journal of Health and Environmental Research (KOJHER) is a no page fees journal outfit. However, authors of accepted paper or article shall attract a processing charge which is aimed to assist the management to keep the journal running. Given that this is a no page fees journal, authors of accepted papers are required to stick to a specific number of pages per article not exceeding 15 pages."],["p","Contact"],["p","Submissions accepted for publication must be by email only. For submission of manuscripts and other related matters regarding the journal, please contact:"],["p","Editor in Chief: Prof. Jacinta Opara"],["p","KOMU Journal of Health and Environmental Research (KOJHER)"],["p","Kingsley Ozumba Mbadiwe University(KOMU) Ideato-Imo State."],["p","Tel: 07012819173"],["p","Email: [email protected], [email protected]"]]},{"id":58,"cat":"Academics","date":"2024-03-08","title":"ICHER 2024 Conference","by":"Ikechukwu Nosike Dozie","img":null,"sum":"1st International Conference on Health & Environmental Research (ICHER2024) at Kingsley Ozumba Mbadiwe University, Nigeria.","body":[["p","1st International Conference on Health & Environmental Research (ICHER2024) at Kingsley Ozumba Mbadiwe University, Nigeria."],["p","About the Conference"],["p","ICHER2024 will be convened to increase the awareness of scholars, governments and their institutions, the private sector and society at large, about the close relationship between health, environment, and development. The theme of this international conference will provide an ample opportunity for policy/decision makers, researchers, academia, development partners, NGOs and practitioners to explore in-depth the major critical environmental issues which affect citizens, business, and the community at large. The recommendations for action policy and decision-making will provide great opportunities to achieve sustainable development in economic, social and environmental aspects. The vision is to encourage “international transdisciplinary research providing knowledge for understanding, mitigating, and adapting to global environmental change for social and economic growth and advancement in technologies. Considering that the world of today has become a global village, participation is in person or virtual."],["p","Date: Nov 25th-27th, 2024"],["p","Focus:"],["p","· Health & environment connection"],["p","· Sustainability"],["p","Call for papers! Submit research on these topics by July 12th."],["p","Attend the conference!"],["p","In-person or virtual options"],["p","Registration fees:"],["p","Conference Registration: International Local"],["p","Registration: US$150 N40,500"],["p","Registration at Venue US$175 N45,500"],["p","Corporate Participation US$250 N60,000"],["p","Discounted rates for authors of accepted papers"],["p","Learn more & register:"],["p","Email: [email protected] or [email protected]"]]},{"id":56,"cat":"Academics","date":"2023-06-14","title":"KOMU Department of Linguistics Explores the World of Braille at the School of the Blind in a Remarkable Visit","by":"Obinna I Anyanwu","img":null,"sum":"On Thursday, 25th May, 2023, the staff, and students of the Department of Linguistics at Kingsley Ozumba Mbadiwe University (KOMU) embarked on a transformative visit to the Special Education School of the Blind in…","body":[["p","On Thursday, 25th May, 2023, the staff, and students of the Department of Linguistics at Kingsley Ozumba Mbadiwe University (KOMU) embarked on a transformative visit to the Special Education School of the Blind in Afara-Ukwu, Umuahia, Abia State. Led by the esteemed Prof. F.N. Chukwukere, the Dean of the Faculty of Arts, this visit was not merely a fulfilment of academic requirements for the course LIN 107 (Introduction to Braille System) but an embodiment of KOMU's commitment to inclusivity and the holistic development of its students. Prof. Chukwukere, an exemplary figure in the Linguistics field, played an instrumental role in leading the students on this eye-opening academic excursion."],["p","Inclusive Gathering: KOMU Faculty and Students Embrace the School of the Blind"],["p","As the doors of the School of the Blind opened, the KOMU Linguistics students entered a world where touch and sound prevailed over sight. They were greeted by a community where visual impairment was not a hindrance but rather a catalyst for exceptional academic achievement and personal growth. The Linguistics students, armed with their theoretical knowledge gained through coursework at KOMU, were eager to apply their skills and delve deeper into the intricacies of the Braille system."],["p","Under the guidance of Prof. Chukwukere and one non-blind staff member of the School of the Blind, the Linguistics students engaged in dynamic lectures and discussions, eagerly exchanging ideas with their visually impaired counterparts. This event further reinforced the commitment of KOMU to practical, hands-on learning experiences."],["p","The visit to the School of the Blind not only broadened the horizons of the Linguistics students but also instilled in them a deeper appreciation for inclusivity and the transformative power of education. As the Linguistics students bade farewell to the School of the Blind, they carried with them the teachings and experiences that will shape their future endeavours."],["p","Reflecting on the excursion, Prof. Chukwukere expressed her gratitude to the Vice-Chancellor for the opportunity to lead the Linguistics students on this journey of discovery. She commended the students for their active participation and genuine interest in the blind community. In an emotive disposition, Prof. Chukwukere said it was quite pathetic discovering five siblings of same parents from Ngor Okpala Local Government Area of Imo State, who became blind each immediately after clocking the age of four. Aside this she said, every member of the community including the School Principal and the Youth Corps members were blind but apparently exhibited high proficiency in communication."],["p","It is notable that K.O. Mbadiwe University, under the guidance of Prof. Ikechukwu N.S. Dozie, continues to blaze the trail of excellence and scholarship, encouraging students to explore diverse perspectives and engage with communities beyond the confines of their classrooms. It is the expectation of University Management that this excursion would be a catalyst for further meaningful interactions/collaborations aimed at fostering of a more inclusive society."]]},{"id":55,"cat":"Campus","date":"2023-06-05","title":"Commissioner for Education inducts a new tractor at KOMU","by":"Ikechukwu Nosike Dozie","img":"activities/May2026/01KSZWAQV1H76Z1PKE54ARYQC8.jpeg","sum":"On a one-day visit, the Honourable Commissioner for Education inducted a new tractor for the University.","body":[["p","The Hon. Commissioner for Education, Prof. JohnCliff Nwadike and the Special Adviser (SA) K.O. Mbadiwe University, Chief Bona Nwoke Dike paid a one-day visit to the university on Thursday, June 1, 2023. The visit primarily was to induct a brand-new tractor bought by the Management of the University and to assess the state of facilities. The Vice-Chancellor, Professor Ikechukwu Dozie in a brief remark welcomed both officials to the university. He congratulated them and commended Gov. Uzodimma for their appointments in the Shared Prosperity Administration of the Imo State Government."],["p","The Vice-Chancellor, Prof. Dozie; the DVC, Prof Onyeka show the Hon. Commissioner and SA to the Governor some important landmarks in the universityHe briefed the officials on some of the modest achievements of his administration including the successful transition from EPU to KOMU, stable academic calendar with the university about to commence the second semester of the 2022/23 academic session, accreditation of all mature programmes, development of a virtual classroom for e-learning, the commencement of SIWES and JUPEB programmes, introduction of three (3)-new programmes in Architecture, Estate Management and Biology, graduation of the first batch of students etc."],["p","The VC also briefed the officials about future plans of the university including preparations for NYSC mobilization of pioneer graduates, planning the 1st Convocation ceremony with the approval of the Visitor and preparations for NUC repeat Resources assessment of the programmes namely Law, Nursing Science, Medical Laboratory Science, Information Technology, Cyber Security, Forensic Science and Software Engineering and new Resource assessment for Public Health, Environmental Health and Maritime Management Technology."],["p","In their responses, both officials commended the University Management for their dedication/commitment, courage, sacrifice and tenacity which gave rise to the modest achievements made within a short period of time. They promised to brief The Visitor and His Excellency, Senator Hope Uzodimma on some of the challenges facing the institution. They urged Management to remain focused on achieving the objectives of the establishment of the university."],["p","The highpoint of the visit was the induction of a brand-new tractor, FarmTrac, bought by University Management for environmental and agricultural purposes. The Commissioner expressed deep joy that Management could achieve such a feat with her monthly imprest. He urged them to continue to be prudent in the management of resources to create more positive and sustainable impacts. This ceremony was followed by a tour of selected facilities in the institution."],["p","KOMU Management in a group picture with the Hon. Commissioner Prof. JohnCliff Nwadike and the Special Adviser (SA) K.O. Mbadiwe University, Chief Bona Nwoke Dike"]]},{"id":54,"cat":"Academics","date":"2023-04-21","title":"KOMU 2022/2023 First Semester Examinations","by":"","img":null,"sum":"","body":[]},{"id":52,"cat":"Academics","date":"2023-04-08","title":"100% NUC accreditation in the 2022 exercise; JUPEB programme launched","by":"Ikechukwu Nosike Dozie","img":null,"sum":"Physics, Animal & Environmental Biology, Finance & Banking and Linguistics all earned full accreditation in the November/December 2022 NUC exercise.","body":[["p","The Kingsley Ozumba Mbadiwe University Ideato, Imo State has scored another 100% in the recently released results of the 2022 November/December accreditation exercise by the National Universities Commission (NUC). The four (4) programmes which earned FULL accreditation status are: Physics, Animal & Environmental Biology, Finance & Banking and Linguistics."],["p","Speaking with our reporter, the Vice-Chancellor, Professor I.N.S. Dozie confirmed that all mature programmes in the University are accredited. He recalled that during the maiden accreditation exercise in November/December 2021, the University scored 100% in eleven (11) programmes presented securing Full accreditation in eight (8) programmes and Interim accreditation in three (3) programmes. In addition, he confirmed that the institution had just received approval to start JUPEB programme in the 2023/24 academic session."],["p","He thanked the staff for great sacrifice and devotion to duty despite the teething challenges associated with early growth and development. He expressed deep appreciation to His Excellency, Governor Hope Uzodimma and Visitor to the University for generous support to the institution."],["p","The Vice-Chancellor appealed to applicants seeking quality and uninterrupted education and mentorship and a great experience after graduation to choose KOMU as their institution of first choice or effect change of institution to KOMU."],["p","He assured that the University Management was committed to making KOMU a first-choice destination in a short time due to the many student-friendly policies of the university. Such include rich curricula emphasizing entrepreneurship and leadership education, and vocational and skills acquisition driven by innovative technology as well as graduates receiving degree certificates during convocation and transcripts upon demand."],["p","K.O. Mbadiwe University, a public institution, was established in 2016 as the 42nd State University in Nigeria with the mission to train talented men and women with passion and skills to apply knowledge and technology sensibly to solve the problems of the nation and the global community at large. The institution driven by the core values of integrity, excellence, teamwork, innovation and collaboration produced her first graduates in the 2021/2022 academic session."],["p","Prepared by:"],["p","KOMU PR UNIT"]]},{"id":51,"cat":"Academics","date":"2023-03-20","title":"KO Mbadiwe University Gets Approval to Commence JUPEB Programme","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Kingsley Ozumba Mbadiwe University (KOMU) Ideato, Imo State has received approval to commence the Joint University Preliminary Examination Board (JUPEB) programme in the institution. This was sequel to a…","body":[["p","The Kingsley Ozumba Mbadiwe University (KOMU) Ideato, Imo State has received approval to commence the Joint University Preliminary Examination Board (JUPEB) programme in the institution. This was sequel to a re-accreditation visit to the university by a three-man JUPEB team lead by the Registrar/CEO, Professor Wale Okunuga held between January 24-25, 2023. The letter to the Vice-Chancellor signed by the JUPEB Registrar & CEO conveying the approval stated, “I am pleased to inform you that the Chairman on behalf of the Governing Board has approved the recommendation of the Re-assessment Team that the affiliation status of Kingsley Ozumba Mbadiwe University be reviewed from Interim Affiliation to Full Affiliation Status”."],["p","This approval has been received with tremendous joy by the KOMU community which had desired the commencement of this programme to assist applicants exploit fully the benefits of increased access to university education in Imo State driven by the Governor Hope Uzodinma’s administration as envisioned in the 3-R Mantra."],["p","The Vice-Chancellor, Professor I.N.S. Dozie is confident that this positive development will afford prospective applicants’ another opportunity to benefit from quality and uninterrupted education and mentorship being offered at KOMU. He expressed deep appreciation to the Visitor of the institution, His Excellency Governor Hope Uzodinma for generous support to the sustained growth and development of the institution."],["p","It is noteworthy that the JUPEB programme is a preliminary Direct Entry examination that places successful candidates in the second year of study in the University as an equivalent of the Advanced Level (A/L) programme conducted by the West African Examination Council (WAEC)."],["p","The CEO & Registrar of JUPEB in a warm hand-shake with the Vice-Chancellor K.O. Mbadiwe University, Ideato"]]},{"id":50,"cat":"Academics","date":"2023-03-01","title":"K.O. Mbadiwe University (KOMU) Celebrates 2023 World NTD Day","by":"Ikechukwu Nosike Dozie","img":null,"sum":"As part of her commitment towards educating and conducting sensitization on various topical global issues as envisioned by her mandate of establishment, the Kingsley Ozumba (K.O.) Mbadiwe University Imo State joined the…","body":[["p","As part of her commitment towards educating and conducting sensitization on various topical global issues as envisioned by her mandate of establishment, the Kingsley Ozumba (K.O.) Mbadiwe University Imo State joined the global health community to celebrate the 2023 World Neglected Tropical Diseases (NTD) Day."],["p","The ceremony took place on Tuesday January 31, 2023 and featured a Road Walk on awareness on the ways to prevent the spread of NTDs within the university community and the neighbouring host communities. This was followed by a lecture delivered by a renowned parasitologist, Dr. Mrs. Nkeiru Kamalu of the Department of Animal and Environmental Biology. In her lecture, Dr. Kamalu stressed that NTDs can be prevented through regular handwashing with soap and running water and maintaining a clean environment. She demonstrated to participants the proper technique for handwashing."],["p","Dr. Kamalu on a field work with the StudentsShe defined NTDs are a category of 20 diseases that are mostly found in the tropics."],["p","These conditions include Chagas disease, leishmaniasis, leprosy, rabies, Buruli ulcer, dengue fever, lymphatic filariasis (elephantiasis), human African trypanosomiasis (HAT) (sleeping sickness), dracunculiasis (guinea worm disease), onchocerciasis (river blindness), schistosomiasis, soil-transmitted helminthiasis (ascariasis, hookworm, trichuriasis), echinococcosis, food-borne trematodiasis, cysticercosis/taeniasis, trachoma, and yaws."],["p","According to her they cause devastating health, social and economic consequences to more than one billion people in the world with majority living in the tropics."],["p","KOMU Staff and Students Celebrates World NTD Day 2023"],["p","She noted that the symptoms of NTDs differ greatly from one disease to another. Some are acute while others such as sleeping sickness, leprosy, and guinea-worm disease are chronic in nature. She posited that NTDs rarely cause death, but they can cause significant disability that persists for a lifetime."],["p","Unlike some common infectious diseases, most NTDs in general do not spread widely; they pose little risk to people in high-income countries. Instead, climate and its effects on the distribution of vectors and reservoir hosts in addition to poor socio-economic conditions limit their distribution largely to the tropics."],["p","In his address, the Vice-Chancellor, Prof. I.N.S. Dozie said that KOMU was committed to educating the host communities and the public on various issues of global importance such as the World NTD Day. He urged the participants to wash their hands regularly with soap and running water and encouraged them to maintain good environmental hygiene."],["p","He thanked the Department of Animal and Environmental Biology for conceiving and executing successfully the 2023 World NTD Day whose theme was: “Act now, Act together, Invest in NTDs”."],["p","KOMU Students listen with apt attention"]]},{"id":49,"cat":"Academics","date":"2023-02-26","title":"Kingsley Ozumba (K.O.) Mbadiwe University (KOMU) Ideato Holds 5th Matriculation Ceremony","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Kingsley Ozumba Mbadiwe University (KOMU) Ideato, Imo State, an emerging pride in quality and uninterrupted education held her 5th Matriculation ceremony on Thursday, February 16, 2023, in the University Senate…","body":[["p","The Kingsley Ozumba Mbadiwe University (KOMU) Ideato, Imo State, an emerging pride in quality and uninterrupted education held her 5th Matriculation ceremony on Thursday, February 16, 2023, in the University Senate Chamber. The historic event was witnessed by parents and guardians, top government officials, members of the host communities, gentlemen of the press and a host of others."],["p","In his Matriculation address, the Vice-Chancellor, Professor I.N.S. Dozie advised the students to let the matriculation oath be a guiding compass throughout the period of their education. He urged them to make diligent use of the modest facilities in the school, especially the library that has lots of resources such as ProQuest, Research for Life and a host of open sources such as OpenLearn, CosmoLearning, MIT Open, Yale Open, etc. He listed the benefits of studying at KOMU to include; stable academic calendar, timely graduation of students, quality teaching and mentorship, accredited programmes, good students’ experience on graduation [collection of transcript and degree certificate on graduation], affordable fees, impressive facilities for teaching and learning and for recreational purposes, modest ICT facilities [robust and interactive website, virtual classroom for online teaching and learning and other academic purposes], smart and secure campus with great ambience for teaching and learning, friendly host communities and experienced Management team."],["p","The VC and Principal Officers in a group photo with matriculants"],["p","He cautioned them against involvement in anti-social behaviours such as fighting, bullying, cultism, examination misconduct, use of drugs and alcohol, smoking, rape, stealing, sexual harassment, forgery, threats etc. He emphasized that every student must be found worthy in learning and in character to earn the prestigious degree of the university. He informed the freshmen that the University Senate gave various sanctions to nine (9) students in the 2022/23 academic session ranging from warning to rustication for one academic session and indefinite suspension. He further advised them to maintain good personal and environmental hygiene and to observe and respect the customs, cultures, and traditions of the host communities. Finally, he assured parents that University Management will do her best to give their children and wards quality training and comprehensive education as encapsulated in the institutional philosophy. The Vice-Chancellor thanked His Excellency Senator Hope Uzodimma, The Governor of Imo State and Visitor to the University for unstinted support to the institution and the premium placed on education in the State. A total of 180 students in the Faculties of Science, Arts, Environmental Sciences and Social & Management Sciences took the matriculation oath."],["p","The Kingsley Ozumba (K.O.) Mbadiwe University was created as a public institution by the Imo State of Nigeria Law No. 1 of 2021 to replace the former Eastern Palm University which was established in 2016 as the 42nd State University in Nigeria and 143rd in the Nigerian University System. The mission of KOMU is to “produce talented men and women with passion and skills to apply knowledge and technology sensibly to solve the problems of the nation and the global community at large”."]]},{"id":48,"cat":"Academics","date":"2023-02-01","title":"KO Mbadiwe University Hosts JUPEB Team on Re-Accreditation of JUPEB Programme","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Kingsley Ozumba Mbadiwe University Ideato hosted a three-man team from the Joint University Preliminary Examination Board (JUPEB) led by the Registrar/CEO, Professor Wale Okunuga. The team which arrived on Tuesday,…","body":[["p","The Kingsley Ozumba Mbadiwe University Ideato hosted a three-man team from the Joint University Preliminary Examination Board (JUPEB) led by the Registrar/CEO, Professor Wale Okunuga. The team which arrived on Tuesday, January 24, 2023, visited the University on Wednesday, January 25, 2023, to inspect facilities in readiness for the commencement of the JUPEB programme in the university during the 2023/2024 academic session. At the Exit meeting, the JUPEB Registrar expressed satisfaction with the facility tour and interaction with staff of the programme and commended Management for adequate preparations for the exercise. In his welcome remarks, the Vice-Chancellor, Professor I.N.S. Dozie assured the JUPEB Team of the readiness of the institution to commence the programme once the approval is granted. It is notable that the JUPEB programme is preliminary direct entry examination that places successful candidates in the second year of study in the University as an equivalent of the hitherto Advanced Level (A/L) programme conducted by the West African Examination Council (WAEC). The Vice-Chancellor emphasized that KOMU is exploring all possible avenues to encourage prospective applicants to exploit fully the benefits of increased access to university education in Imo State driven by Governor Hope Uzodinma’s administration as envisioned in the 3-R Mantra. He expressed appreciation to Governor Uzodinma for his unstinted support to the sustained growth and development of the institution. The Vice-Chancellor is optimistic that by the end of the current 2022/2023 academic year, all active programmes in the University would have received accreditation by the National Universities Commission (NUC) in addition to the JUPEB Programme. This positive development will afford prospective Imo applicants various opportunities to enter the University to benefit from the quality and uninterrupted education and mentorship being offered."]]},{"id":47,"cat":"Leadership","date":"2022-11-23","title":"KOMU VC Bags Another Award","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-Chancellor, Kingsley Ozumba Mbadiwe University Ideato, Prof. Ikechukwu Nosike Simplicius Dozie was honoured with the Most Outstanding Vice-Chancellor (Southeast) Award by the Association of Beauty Queens and…","body":[["p","The Vice-Chancellor, Kingsley Ozumba Mbadiwe University Ideato, Prof. Ikechukwu Nosike Simplicius Dozie was honoured with the Most Outstanding Vice-Chancellor (Southeast) Award by the Association of Beauty Queens and Kings, an affiliate of the National Tourism Board. The event which took place at the Anniversary Celebration/Thanksgiving Service of the Association held on Friday, October 28, 2022, at the Prevailing Destiny Center, Uyo, Akwa Ibom State, was attended by prominent personalities including an array of crowned beauty queens and kings in Nigeria."],["p","In presenting the award, the association’s National President, Evangelist Ukeme Michael stated that Prof. Dozie was nominated on merit, after a meticulous screening by a committee established for that purpose. He said that the award was in recognition of the Vice Chancellor’s outstanding contributions to the development of the educational sector, philanthropic gestures, and human capital development."],["p","The Vice-Chancellor who was the Special Guest of Honour at the occasion was represented by the University Public Relations Officer (PRO), Barr. Ekene Bob-Ekechukwu. In his response, the Vice Chancellor thanked the association for the recognition. He expressed delight with the vision of the association which is the rebranding of the tainted image of beauty pageants by making positive impacts on society."],["p","He also applauded the humanitarian gestures of the association in reaching out to the victims of recent flooding in some parts of Nigeria and the sensitization of the masses on the need to collect their Permanent Voters Card (PVC) in order to participate in the forthcoming general elections. The Vice-Chancellor assured the association of partnership with the University in areas of common interest and urged members to continue to be good role models to the youth."],["p","Previously, Executives of the Association led by the National President had paid a courtesy visit to the Vice Chancellor who received them along with other Principal Officers of the University at the temporary University Liaison Office in Owerri, the Grand Amari Hotel, Egbeada Owerri, Imo State. During the visit, the Executives who took turns to address the Vice Chancellor had eulogized him as a pacesetter in the education sector. Stressing that his outstanding achievements in the education sector especially in the area of human capital development had endeared the association to him. They presented the Vice Chancellor with a souvenir and an Ambassador of Youths Award. Furthermore, they notified him of his nomination for the Most Outstanding Vice-Chancellor (Southeast) Award."],["p","Ekene Bob-Ekechukwu"],["p","Public Relations Officer"]]},{"id":46,"cat":"Leadership","date":"2022-11-23","title":"KOMU VC Visits Archbishop Ugorji","by":"","img":null,"sum":"The Vice Chancellor of Kingsley Ozumba Mbadiwe University Ideato, Prof I.N.S Dozie, paid a courtesy visit to the Archbishop of the Owerri Catholic Diocese, His Grace, Most Rev Lucius Ugorji on Tuesday, October 25, 2022.…","body":[["p","The Vice Chancellor of Kingsley Ozumba Mbadiwe University Ideato, Prof I.N.S Dozie, paid a courtesy visit to the Archbishop of the Owerri Catholic Diocese, His Grace, Most Rev Lucius Ugorji on Tuesday, October 25, 2022. The Vice-Chancellor who was accompanied by his lovely wife Dr. Chinomso Dozie, Principal Officers, and some staff of KOMU met with the Archbishop at the Arch Diocesan Secretariat, Assumpta Cathedral Owerri."],["p","During interactions, the Vice Chancellor congratulated the archbishop on his elevation as the Chief Shepard of the Owerri Ecclesiastical Province. He presented the archbishop with the vision and mission of his administration. He also highlighted some of the achievements of his administration which include, the successful completion of the 2021/2022 academic session without interruption, accreditation of programmes, graduation of the first set of students (i.e. pioneers), digitalization of activities in the University for e-teaching and learning; e-administration including timely processing of results and timely production of transcripts etc, expansion of academic programmes, etc. The Vice Chancellor promised that his team is committed to changing the existing narrative and offer students a new experience in education and mentorship."],["p","In addition, he highlighted some challenges experienced by his administration which include perception of insecurity, funding, poor enrolment of prospective students etc. He called on the Church to partner with the University, particularly in the area of publicity/sensitization of the public about the university."],["p","In his reply, the archbishop welcomed the Vice Chancellor and his entourage. He extolled the administrative qualities of the Vice Chancellor and commended him for steering the ship of the institution in the right direction. He also pledged to support the University in the area of sensitization and urged the Vice Chancellor not to relent in his quest to develop the University to achieve the mandate of the establishment."],["p","The high point of the meeting was the presentation of some university publications and souvenirs to the archbishop. The much admired and respected cleric also blessed the Vice Chancellor and his entourage and prayed for the success of his administration."],["p","Ekene Bob-Ekechukwu Esq."],["p","Public Relations Officer"],["p","Kingsley Ozumba Mbadiwe University, Ideato."]]},{"id":45,"cat":"Academics","date":"2022-10-18","title":"Bi-Annual Meeting of the Association of University Librarians of Nigerian Universities","by":"","img":null,"sum":"The University Librarian attended the 107th Bi-annual meeting of the Association of University Librarians of Nigerian Universities (AULNU) held at Prof. Idris Abdulkadir Auditorium, National Universities Commission, No…","body":[["p","The University Librarian attended the 107th Bi-annual meeting of the Association of University Librarians of Nigerian Universities (AULNU) held at Prof. Idris Abdulkadir Auditorium, National Universities Commission, No 26 Aguiyi Ironsi Street Maitama District, Abuja from Sunday 25th to Friday 30th September 2022. The theme of the meeting is LIS Education and Practice in Nigeria: Bridging the Gap between Theory and Efficient Information Service Delivery. As notably posited by Yogi Berra, “in theory there is no difference between theory and practice, in practice there is”. Thus this conference theme looked into the transitioning of theory to practice whilst identifying its peculiarities and proffering, through elaborate and insightful discussion, solutions that would mitigate the effects of the identified gaps between theory and practice, as well as ensure that LIS curriculum is such that produces the expected products for the job market."],["p","There was also a training session for New University Librarians, with the training bordering on Academic and Research Functions of University Librarians; Relationships of University Librarians Within and Outside the University; General Schedule, and Professional Duties of University Librarians. It was indeed a knowledge-packed outing."]]},{"id":44,"cat":"Academics","date":"2022-10-18","title":"LITT 2022 16th Library and Information Technology Today","by":"","img":null,"sum":"University Librarian reading the citation of the Keynote Speaker of LITT 2022 Workshop and Conference.","body":[["p","University Librarian reading the citation of the Keynote Speaker of LITT 2022 Workshop and Conference."],["p","The University Librarian attended the 16th Library and Information Technology Today (LITT) Workshop at Ignatius Ajuru University of Education, Rumuelumeni, Port Harcourt, Rivers State from Monday 3rd to Friday, 7th October 2022. The theme of the Workshop was Blockchain Technology in Library and Information Centres: Benefits and Best Practices. The University Librarian of Kingsley Ozumba Mbadiwe University (KOMU), Ogboko presented KOMU branded gift items to Prof. Mrs Anthonia Omehia who attended the workshop. The presentation made to Prof. A. Omehia signified the establishment of a relationship between the distinguished professor of Library and Information Science and Kingsley Ozumba Mbadiwe University."],["p","Presentation of KOMU branded gift items to a Distinguished Professor of Library and Information Science, Prof. Anthonia Omehia at the just concluded LITT 2022 Workshop and Conference."]]},{"id":43,"cat":"Campus","date":"2022-09-28","title":"KOMU Staff Donates Books to the University","by":"Ikechukwu Nosike Dozie","img":null,"sum":"There seems to be no ending to the deluge of good news emanating from Kingsley Ozumba Mbadiwe University Ideato, as a staff donates books to the University.","body":[["p","There seems to be no ending to the deluge of good news emanating from Kingsley Ozumba Mbadiwe University Ideato, as a staff donates books to the University."],["p","In a ceremony attended by management and staff of the University on Wednesday at the Senate Building, the Vice Chancellor, Prof. I. N. S Dozie received a set of Law books from Barr. Obinna Igwe, who also is the Executive Assistant to the Vice Chancellor and Acting Coordinator of the Legal Unit."],["p","In his presentation, Barrister Igwe stated that he was compelled by the passion and dedication of the University management ably led by Prof. Dozie to donate the books to equip the law library for the proposed Law Faculty. In addition, he said that he was also driven by love and service to humanity to donate the books which would be useful to would-be students of the Law Faculty. Stressing that these were the motivating factors that convinced him to part with the books which originally were part of his library while he was in private practice as a lawyer."],["p","The Vice-Chancellor in his remarks stated that he received the books on behalf of the Visitor of the University, Distinguished Senator Hope Odidika Uzodinma. He cited the issues of inadequate staff and library facilities as the key factors that initially denied the University the Nigerian Universities Commission (NUC) approval to commence a Law Faculty. He said that the donation would go a long way to complement management's effort to equip the law library and to secure the NUC approval to commence a Law Faculty in the University."],["p","He referred to Barr. Igwe's action as being patriotic and opined that the responsibility of education shouldn't be abandoned to the government. He called on well-meaning citizens to emulate Barr. Igwe and partner with the government to develop the education sector. Prof. Dozie vowed that management will not rest it's oars until the University achieves a level of global competitiveness and world-class status."],["p","Ekechukwu Bob-Ekechukwu Esq"],["p","Public Relations Officer"]]},{"id":42,"cat":"Campus","date":"2022-09-27","title":"KOMU Holds 2nd Ecumenical Thanksgiving Service to Mark the Vice-Chancellor’s One Year in Office","by":"Ikechukwu Nosike Dozie","img":null,"sum":"It was all praises and thanksgiving on Thursday, 22nd September 2022 as Kingsley Ozumba Mbadiwe University, Ideato held its 2nd Ecumenical Thanksgiving Service to mark the Vice–Chancellor’s one year in office. The…","body":[["p","It was all praises and thanksgiving on Thursday, 22nd September 2022 as Kingsley Ozumba Mbadiwe University, Ideato held its 2nd Ecumenical Thanksgiving Service to mark the Vice–Chancellor’s one year in office. The occasion which took place at the Senate Building of the University, had in attendance the Visitor, His Excellency, Distinguished Sen. Hope Uzodinma ably represented by the Sole Administrator Ideato South Local Government Area, Pastor Bede Ikeaka, the Vice-Chancellor, Prof. Ikechukwu N. S Dozie, his lovely wife Dr (Mrs.) C.P. Dozie and Principal Officers of the university. Other dignitaries who graced the event were the traditional rulers of the host communities led by the Chairman Ideato Council of Traditional Rulers, His Royal Highness, HRH Eze G.A. Ezeihekaibee (V), Ezeukwu and the Clan Head of Umuma-Ebenmano and a host of other dignitaries."],["p","The Ecumenical Thanksgiving Service was moderated by Rev. Fr. (Prof.) Jude Onuoha, Venerable Kelechi Okere, Rev. Fr. Jude Onyeakazi and Rev. Fr. Dr. Nath Okwara, who is also the University/Host Community Liaison Officer. During the service, prayers and thanksgiving were offered to God for the peace and progress of the University. While blessing all in attendance, the priests also prayed for God to grant the Visitor, the Vice-Chancellor and the Principal Officers wisdom and synergy to take the University to greater heights."],["p","In his state of the University address titled: “Accelerating Our Progress To Global Competitiveness And World-Class Status- A First Year Assessment”, Prof. Dozie thanked God Almighty who made it possible for him to mark his first year in office. He also appreciated the Visitor, Governor Uzodimma for his appointment as Vice-Chancellor and for his generous support to the University. The Vice-Chancellor reeled out his modest achievements within the period in review which included a smooth transition from Eastern Palm University to Kingsley Ozumba Mbadiwe University, approval of the University’s domain name by the Nigerian Internet Registration Association (NIRA) and development of the website, regular payment of workers’ salary by government and the release of the 2021/2022 promotion exercise of pioneer staff. In addition to these were procurement of 4. nos. Toyota fairly used vehicles for Principal Officers, completion of teaching staff recruitment exercise, 100% NUC accreditation result for 11 programmes, introduction of new academic programmes, development of virtual classroom for on-line teaching and learning, provision of 100 E-pads for staff and student’s use donated by NCC, staff capacity building trainings, improvement of student’s welfare, regular consultations with host communities and a host of others. He admonished staff to renew their commitment to duty and vowed not to relent until the University attains a commendable level of global competitiveness and world-class status."],["p","Speaking through his representative, the Visitor assured the University community of government’s continued support. Furthermore, the governor advised the traditional rulers of the host communities to partner with University Management to ensure the actualization of the aims and objectives of the University."],["p","The high point of the occasion was the cutting of the anniversary cake and the award of certificates of merits and prizes to deserving staff namely the overall best staff (ie KOMU staff of the year 2021/2022), best academic staff, best non-teaching staff (senior category), best non-teaching staff (junior category) and best security personnel."],["p","Ekene Bob-Ekechukwu"],["p","Public Relations Officer."]]},{"id":41,"cat":"Admissions","date":"2022-09-02","title":"Admission into the Undergraduate Academic Programmes of K.O. Mbadiwe University (KOMU)","by":"Ernest Onuoha","img":null,"sum":"KOMU invites qualified candidates, who desire admission into its NUC–approved undergraduate academic programmes for the 2022/2023 academic session.","body":[["p","KINGSLEY OZUMBA MBADIWE UNIVERSITY"],["p","IDEATO, IMO STATE"],["p","ADMISSION FOR THE 2022/2023 SESSION"],["p","ADMISSION! ADMISSION! ADMISSION!"],["p","KOMU invites qualified candidates, who desire admission into its NUC–approved undergraduate academic programmes for the 2022/2023 academic session."],["p","AVAILABLE COURSES:"],["p","Faculty of Sciences:"],["li","Biochemistry (B.Sc.)"],["li","Microbiology (B.Sc)"],["li","Chemistry (B.Sc)"],["li","Biology (B.Sc)"],["li","Mathematics (B.Sc)"],["li","Statistics (B.Sc)"],["li","Computer Science (B.Sc)"],["li","Physics (B.Sc)"],["li","Plant Science & Biotechnology (B.Sc)"],["li","Animal & Environmental Biology (B.Sc)"],["p","Faculty of Social & Management Sciences:"],["li","Accounting (B.Sc)"],["li","Business Administration (B.Sc)"],["li","Banking & Finance (B.Sc)"],["li","Economics (B.Sc)"],["li","Political Science (B.Sc)"],["li","Sociology (B.Sc)"],["li","Psychology (B.Sc)"],["li","Entrepreneurship (B.Sc)"],["li","Marketing (B.Sc)"],["li","Industrial Relations & Personnel Management(B.Sc)"],["p","Faculty of Arts:"],["li","English Language & Literary Studies (B.A)"],["li","History & International Studies (B.A)"],["li","Linguistics (B.A)"],["li","Philosophy (B.A)"],["p","Faculty of Environmental Sciences:"],["li","Architecture (B.Sc)"],["li","Estate Management (B.Sc)"],["p","QUALIFICATION"],["p","To qualify for admission into KOMU undergraduate programmes, prospective candidates must have sat for the 2022 UTME, irrespective of whether or not the candidates chose KOMU as their first-choice institution. However, candidates who did not choose KOMU as their first-choice institution, are to effect change of institution on JAMB website. The required minimum UTME score is 140."],["p","Furthermore, DIRECT ENTRY candidates, who possess any of A/levels, JUPEB, NCE, ND, HND, Degree certificates in relevant subjects/disciplines are also qualified to apply."],["p","POST UTME SCREENING FEE"],["p","The fee for screening is two thousand naira (₦2000) only. All payments should be made using the Remita payment gateway."],["p","HOW TO APPLY FOR KOMU POST-UTME SCREENING EXERCISE"],["p","I. Visit the KOMU website at www.komu.edu.ng"],["p","II. Click on “Online Application”"],["p","III. Click on “Apply Online” and read the instructions"],["p","V. Click on “Start your Admission Process”"],["p","VI. Click on “Start Application Process”"],["p","VII. Fill out the form completely and correctly"],["p","VIII. Click on the “Submit”"],["p","IX. You will be directed to pay the Post-UTME/Direct Entry screening fee of ₦2000 only."],["p","X. Pay online with your Card or use any of the other available Remita payment options convenient to you."],["p","XI. Print the Acknowledgement slip, which is also sent to your email"],["p","XII. Bring your Acknowledgement slip to the University on the Post-UTME screening day."],["p","Signed"],["p","ERNEST ONUOHA"],["p","Registrar, KOMU"],["p","For further enquiries, please contact the relevant officer of the University, using the following number: 0806 072 2027"]]},{"id":40,"cat":"Leadership","date":"2022-08-05","title":"KOMU Scores Another Milestone","by":"","img":null,"sum":"The Management of Kingsley Ozumba Mbadiwe University (KOMU) Ideato, ably led by the scholarly Vice Chancellor, Prof I.N.S Dozie has scored another innovative milestone in the academic sphere. This milestone was achieved…","body":[["p","The Management of Kingsley Ozumba Mbadiwe University (KOMU) Ideato, ably led by the scholarly Vice Chancellor, Prof I.N.S Dozie has scored another innovative milestone in the academic sphere. This milestone was achieved with the introduction of the Virtual Classroom. This innovation enables both students and staff to interact and engage in lectures virtually from any location where they may be."],["p","Recently, the University commenced the training of staff and student in order to get them acquainted with the new technology. This virtual training of staff and students is being anchored by the Deputy Vice Chancellor, Prof. A. C. Onyeka who also is a renowned expert in the Information Communication Technology (ICT) field."],["p","The essence of this Virtual Classroom is to ensure an uninterrupted academic activity in the University, especially in this period of insecurity where staff and student may sometimes be compelled to work and study from home."],["p","According to the Vice Chancellor Prof. Dozie, this development has put KOMU in the category of international higher institutions where students and staff can seamlessly work and study from any where. This according to him is in line with the international best practices where academic activities are now IT driven."],["p","He further stated that this achievement is in tandem with the 3R Shared Prosperity programme of His Excellency, the Executive Governor of Imo State, Senator Hope Uzodinma. In his opinion, one of the key visions of the 3R Shared Prosperity programme is the promotion of academic excellence in the State, which has been reflected in the support the government has given to the University so far."],["p","The Vice Chancellor vowed not to rest on his oars in the pursuit of academic excellence and the placement of the University among the committee of reputable higher institutions in Nigeria and beyond."],["p","Ekene Bob-Ekechukwu"],["p","Public Relations Officer"]]},{"id":39,"cat":"Leadership","date":"2022-07-27","title":"KOMU Participates in the 2022 Policy Meeting and the 2020 National Tertiary Admissions’ Performance-Merit Award (Natap-M Award)","by":"Ernest Onuoha","img":null,"sum":"The Jamb Admissions and Matriculation Board (JAMB) in the discharge of its statutory function of holding annual meetings with various stakeholders to discuss policy issues concerning admissions into the Nigerian…","body":[["p","The Jamb Admissions and Matriculation Board (JAMB) in the discharge of its statutory function of holding annual meetings with various stakeholders to discuss policy issues concerning admissions into the Nigerian University System, convened the 2022 Policy Meeting on Thursday 21st July 2022 at the International Conference Center Abuja. The Hon. Minister of Education, Malam Adamu Adamu was the Chairman of the meeting and gave a brief address on the Policy Directives of the 2022 exercise. The Chief Host and Registrar of JAMB, Professor Is-Haq O. Oloyede gave an update on the 2021 Admissions exercise and the 2022 UTME/DE performances as well as a memorandum to the 2022 Policy meeting on plans and modalities for the conduct of admissions to tertiary institutions in Nigeria. It is noteworthy that the 2022 Policy meeting approved the minimum institutional score of 140 marks in Nigerian universities irrespective of ownership."],["p","A major highlight of the 2022 JAMB Policy meeting was the 2020 National Tertiary Admission’s Performance-merit award, where some institutions were rewarded with cash prizes for compliance with certain aspects of the admission process. The categories of the awards included:"],["p","a.The 2020 Institution of First Choice for Candidates to Tertiary Institutions in Nigeria."],["p","b.The Most National Institution in 2020 Admission."],["p","c.The 2020 Most Improved Institution in Gender Balance"],["p","d.The Institution with the Highest Number of International Students in 2020 Admission"],["p","e.The Most Compliant Institution in keeping to the Guidelines in 2020 Admission."],["p","The Vice-Chancellor, Professor Ikechukwu N.S. Dozie participated in the One (1) day Policy meeting in the company of the Registrar, Mr. Ernest Onuoha and the University Admissions Officer, Mrs. Nkeiruka Adioha."]]},{"id":38,"cat":"Leadership","date":"2022-07-27","title":"The VC Participates in the 2022 Retreat for Vice-Chancellors of All State Universities in Nigeria","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-Chancellor, Professor Ikechukwu N.S. Dozie participated in a one-day Retreat for Vice-Chancellors of State Universities in Nigeria held on Wednesday, July 20, 2022, at the National Universities Commission (NUC)…","body":[["p","The Vice-Chancellor, Professor Ikechukwu N.S. Dozie participated in a one-day Retreat for Vice-Chancellors of State Universities in Nigeria held on Wednesday, July 20, 2022, at the National Universities Commission (NUC) Abuja. The Retreat organized by NUC Management was aimed at interacting with Vice-Chancellors on various topical issues in the Nigerian University System in line with emerging trends and global best practices for improved delivery of quality university education in Nigeria."],["p","The retreat, which was chaired by the Executive Secretary of the National Universities Commission, Professor Abubakar Adamu Rasheed was a huge success as various topical issues concerning the Nigerian University System were discussed."],["p","Amongst the topics discussed were:"],["li","Guidelines on Trans-National Education (TNE) in Nigeria"],["li","NUC Ranking of Universities: National University Ranking Advisory Committee (NURAC)."],["li","Core Curriculum Minimum Academic Standards (CCMAS)"],["li","Guidelines on e-Learning in Nigerian Universities"],["li","Guidelines on Visiting, Sabbatical and Adjunct Appointments in Nigerian Universities"],["li","University Convocation and Ceremonies"],["li","Matters Arising from the October/November 2021 Accreditation Exercise"],["li","Guidelines on Funding and Payment Operations for Accreditation and Resource Verification and other NUC Quality Assurance Activities"],["li","Clarification on the Length of Semester in the NUS"],["li","Data Generation from Universities: Integrity and Early Response Issues"],["li","Guidelines on Entrepreneurship in Nigerian Universities"],["li","Nigerian Universities Research and Development Fair (NURESDEF)"],["li","Religious Tolerance in Universities."],["p","Some members of NUC Management at the Retreat were Mr. Chris Mayaki, Deputy Executive Secretary (Administration), who was also the Chairman of the Local Organizing Committee and Dr. Noel Saliu, Director of Academic Planning."]]},{"id":37,"cat":"Academics","date":"2022-07-27","title":"KOMU University Librarian Becomes VP (IT Section) Nigerian Library Association; Gives Lecture on Artificial Intelligence","by":"","img":null,"sum":"K.O. Mbadiwe University Librarian, Dr. Mrs. Nwaohiri N.M. participated in the Nigerian Library Association's National Conference and Annual General Meeting (AGM) in Abuja from July 3 to July 7, 2022. At this conference,…","body":[["p","K.O. Mbadiwe University Librarian, Dr. Mrs. Nwaohiri N.M. participated in the Nigerian Library Association's National Conference and Annual General Meeting (AGM) in Abuja from July 3 to July 7, 2022. At this conference, she was one of the speakers and gave a paper with the title \"Disruptive Potential of Artificial Intelligence: Journey So Far in Nigerian Academic E-Library Services.\" During the National Conference of the Nigerian Library Association, she was also elected to serve as Vice President of the Information Technology Section of the Association."],["p","In a related development, the University Librarian also attended a three-day short course on driving competitive advantage in organisations through Innovative Knowledge Management Practices (for information practitioners, librarians, corporate workers, managers, entrepreneurs, and business stakeholders), from July 18th to July 20th, 2022, at the African University of Science and Technology (AUST), Abuja. The three-day short course introduced university librarians, information practitioners, corporate employees, managers, entrepreneurs, and business stakeholders to the concepts, theories, and models of knowledge management for organizations/institutions, as well as how innovative knowledge management practices contribute to the actualization of competitive advantage in organizations/institutions."],["p","After the brief course, participants were able to process, store, retrieve, and disseminate data and information obtained throughout daily chores to gain a competitive advantage over rivals in business or academic settings. As data, information, and the packaging of information is the \"New Crude Oil\", Innovative Knowledge Management should therefore serve as a guide for reviewing assigned job roles and identifying how it contributes directly or indirectly to institutional growth and development to ensure appropriate and accurate documentation of procedures, assignments, projects, proper handover, consistency, and continuity within institutions. A certificate of attendance was given to each participant at the end of the course."]]},{"id":36,"cat":"Partnerships","date":"2022-07-27","title":"ITF Establishes SIWES Unit at KO Mbadiwe University Ideato","by":"","img":null,"sum":"The Industrial Trust Fund (ITF), a Federal Government Agency saddled with the responsibility of providing Direct Training, Vocational and Apprentice Training, Research and Consultancy Services, Productivity Improvement,…","body":[["p","The Industrial Trust Fund (ITF), a Federal Government Agency saddled with the responsibility of providing Direct Training, Vocational and Apprentice Training, Research and Consultancy Services, Productivity Improvement, and Reimbursement of 50% training contribution paid by employers of labour registered with it, had on Wednesday, July 20, 2022, officially inaugurated the SIWES Unit at the Kingsley Ozumba Mbadiwe University Ideato."],["p","The ITF Area Manager Owerri, Engr. Jonathan Nwaeke said the Agency which administers SIWES programmes was established by Degree 47 of 1971."],["p","In her address, the Representative of the ITF Area Manager, Mrs. Ifeyinwa Ugoji, who was accompanied by the SIWES Coordinator, Mrs. Nnabuihe Rosemary said they were at the University Campus to sensitize the SIWES staff on what was expected of them for effective implementation of SIWES activities in the University. And she promised that ITF will visit the university again to conduct an orientation exercise for the students participating in the SIWES programme."],["p","The Vice-Chancellor of the Kingsley Ozumba Mbadiwe University Ideato, Prof. I.N.S Dozie, represented by the Deputy Vice-Chancellor, Prof. A.C. Onyeka welcomed the ITF staff to KOMU. He described their visit as timely and a confirmation that the application made by the university to the National Universities Commission (NUC) for inclusion in the ITF SIWES programme is receiving due attention. The Vice-Chancellor expressed delight that KOMU is now integrated into ITF programmes and its SIWES scheme."],["p","In a vote of thanks, the University SIWES Director, Prof. I. S. Iwueze thanked the Vice-Chancellor for making it possible for the establishment of the SIWES programme in the University. Furthermore, he expressed deep gratitude to the ITF for the One (1) Day Sensitization Workshop for staff of the University. Prof. Iwueze showed happiness that the training had given the staff a new experience for successful implementation of the SWES programme in the university."],["p","KOMU DVC, Prof. Aloy Onyeka (Centre) with staff of ITF who came to the university for SIWES Unit Establishment/Deliberations"],["p","Story by: Hippo Anyaehie Nwachukwu PR Unit."]]},{"id":35,"cat":"Academics","date":"2022-07-27","title":"KOMU Launches E-Learning Platform: VC Tasks Participants on Proper Use of E-Pads","by":"","img":null,"sum":"The Vice-Chancellor, Kingsley Ozumba Mbadiwe University, Ideato, Prof. I. N. S Dozie, has commended the staff of the university who took part in the first phase of the staff e-learning programme aimed at training the…","body":[["p","The Vice-Chancellor, Kingsley Ozumba Mbadiwe University, Ideato, Prof. I. N. S Dozie, has commended the staff of the university who took part in the first phase of the staff e-learning programme aimed at training the university workforce for excellent service delivery. Prof. Dozie, who was represented at the occasion by the Deputy Vice-Chancellor, Prof. A. C. Onyeka, said that the essence of the training was to assist participating staff in developing capacity/skills for the utilisation of the E-learning platform and modern technology-assisted teaching and learning processes towards maintaining academic excellence in the university."],["p","Participants received training on such areas as the use of virtual classrooms for online lecture delivery; the use of KOMU Google Class Workspace; accessing the e-library materials from the KOMU staff portal; and how to access/navigate through the KOMU staff portal; using staff individual/personalised KOMU email addresses. At the end of the training, most participants were able to create their first Google Class Workspace for an effective e-learning program."],["p","It is noteworthy that the use of the Online/E-Learning Platform is to encourage the delivery of lectures to staff and students from any location. This is a major fallout of the COVID-19 Pandemic that disrupted face-to-face classroom teaching and learning and affected the timely completion of the academic calendars of universities globally. With this development, the management of the university is determined to change the narrative aimed at ensuring a stable academic calendar for the timely graduation of students. It is gratifying that the university is almost completed with the 2021/2022 academic session and will soon commence admission of students for the 2022/2023 academic year."],["p","The high point of the ceremony was the presentation of 40 pieces of E-pads to 40 staff members of the university who participated in the training. The Vice-Chancellor had earlier in his opening address told the participants that 100 pieces of E-pads were donated to the University by the Nigerian Communication Commission (NCC)."],["p","Speaking through the virtual platform, the Acting Director of General Studies, Dr. C. P. Dozie who presented the E-pads on behalf of the Vice-Chancellor, charged the recipients to make good use of the device. She encouraged participants not to rest on their laurels as this is just the beginning of good developments for the university. The DG Director stressed that “the danger in resting on our laurels is that chances are that we may fail to internalise what we have learnt so far given the e-learning we are trying to integrate and imbibe”."],["p","Participants in the first phase of the training included the Principal Officers, Deans, HODs, Professors, Senior Lecturers, and some senior administrative staff. The second phase of the training, according to the Vice-Chancellor, shall include other academic and administrative staff members of KOMU."],["p","Dr. Hillary Akuwudike, acting head of the Department of Economics, gave a vote of thanks on behalf of the participants. He thanked the Vice-Chancellor for the chance to learn how to use virtual classrooms and for giving out the e-pads. He also promised that the staff would put the gadgets to good use to teach and learn more effectively through the online/E-learning platform."],["p","Story by: Hippo Anyaehie Nwachukwu PR Unit"]]},{"id":34,"cat":"Academics","date":"2022-07-18","title":"Commencement of 2021/2022 Second Semester for Freshmen","by":"","img":null,"sum":"The second semester for 2021/2022 session for 100-level students commences on Tuesday, 19th July 2022, having completed their First-semester examination on Friday, 15th of July 2022. The examinations which lasted a…","body":[["p","The second semester for 2021/2022 session for 100-level students commences on Tuesday, 19th July 2022, having completed their First-semester examination on Friday, 15th of July 2022. The examinations which lasted a period of 2 weeks were successful and in line with the vision of management to deliver quality examinations. It’s notable that the Directorate of Quality Assurance monitored the conduct of the examinations and adjudged it to be a successful exercise. 200–400 Level students will begin their revision week from Tuesday, August 2, to Friday, August 5, in preparation for their exams, which start on Tuesday, August 9, 2022."],["p","Story by: Hippo Anyaehie Nwachukwu. PR Unit"]]},{"id":33,"cat":"Campus","date":"2022-07-18","title":"KOMU Plays Host to Students of Charles Heerey Memorial Juniorate Urualla, Ideato North LGA, Imo State","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-Chancellor, Professor I. N. S Dozie has described the Kingsley Ozumba Mbadiwe University, KOMU, Ideato as a smart university campus with a beautiful layout that fits into the concept of today’s modern…","body":[["p","The Vice-Chancellor, Professor I. N. S Dozie has described the Kingsley Ozumba Mbadiwe University, KOMU, Ideato as a smart university campus with a beautiful layout that fits into the concept of today’s modern University, as envisioned by the National Universities Commission, NUC."],["p","Prof. Dozie stated this when the Students of Charles Heerey Memorial Juniorate Urualla paid him a courtesy call at the university campus."],["p","The Vice-Chancellor who took the students down the memory lane in his welcome address said that the Kingsley Ozumba Mbadiwe University was established through the Enactment of the Kingsley Ozumba (KO) Mbadiwe University (Establishment) Law No. 1 of 2021, Imo State of Nigeria by the Imo State House of Assembly and received assent by His Excellency, Senator Hope Uzodimma, Governor of Imo State on 18th February 2021. The Law repealed the Eastern Palm University (Establishment) Law No. 3 of 2016 which was recognized by NUC as the 42nd State University and 143rd in the Nigerian University System. The Law also established the Kingsley Ozumba (KO) Mbadiwe University as a multi-campus university with the Main Campus in Ideato South Local Government Area of Imo State. Thus, NUC recognizes the Kingsley Ozumba Mbadiwe University as the 42nd State University and the 143rd University in the Nigerian University System and as well, the 2nd Imo State-owned University. And as of today, the number of Universities in Nigeria had increased to 215."],["p","In her remarks, the Principal of the School, Rev. Sr. Mary Clare Emechebe, IHM informed the University Management that Charles Heerey Memorial Juniorate Urualla was established in 1971 by Immaculate Heart Sisters, founded in 1946 by Rev. Fr. Charles Heerey, the Archbishop of Onitsha Diocese. Before he died in 1967, he had developed the concept for the establishment of the school. Thereafter his death, the Immaculate Heart Sisters took up the responsibility to establish a secondary school in the memory of the late Archbishop."],["p","The Principal appreciated the Vice-chancellor for finding time out of his busy schedule to receive the students with his Management Team. Sr. Emechebe said they came to KOMU to visit the University facilities as a way to expose the students of the Juniorate to life in the university in preparation for their future endeavors."],["p","The students, mainly from the SS3 class were happy and delighted with seeing the various facilities in the University and expressed their desire to become future students. The students were conducted around the campus by the University Public Relations Unit."],["p","Story by:"],["p","Hippo Anyaehie Nwachukwu."],["p","PR Unit"]]},{"id":32,"cat":"Academics","date":"2022-06-21","title":"K.O. Mbadiwe University (KOMU) Ideato Holds the 4th Matriculation Ceremony","by":"Ikechukwu Nosike Dozie","img":null,"sum":"History was made again at Kingsley Ozumba Mbadiwe University (KOMU) Ideato, Imo State as the institution held her 4th Matriculation ceremony. The event which took place on Friday, June 17, 2022, was witnessed by many…","body":[["p","History was made again at Kingsley Ozumba Mbadiwe University (KOMU) Ideato, Imo State as the institution held her 4th Matriculation ceremony. The event which took place on Friday, June 17, 2022, was witnessed by many people including the parents of the students. The Governor of the State and Visitor to the University, His Excellency, Senator Hope Uzodimma was represented by the Deputy Governor of the State, Professor Placid Njoku. In a brief welcome remark in his office, the Vice-Chancellor Professor Ikechukwu N.S. Dozie expressed great joy at the privilege of having His Excellency in attendance."],["p","He said, “It is extremely rare for a Visitor to find the time out of a usually busy schedule to participate in a matriculation ceremony. Without a doubt, this rare gesture will go a long way towards inspiring and motivating the students and staff of the university to greater achievements. This simply characterizes His Excellency as a loving and caring father. Today’s visit further reassures the KOMU community and the entire state of Imo that His Excellency truly places a very high premium on education”."],["p","In his Matriculation address, the VC advised the students to let the matriculation oath be a guiding compass throughout the period of their education. He urged them to make diligent use of the modest facilities in the school, especially the library that have lots of resources such as ProQuest, Research for Life and a host of open sources such as OpenLearn, CosmoLearning, MIT Open, Yale Open, etc. He cautioned them against involvement in anti-social behaviours such as fighting, cultism, examination misconduct, use of drugs and alcohol, smoking, rape, stealing, sexual harassment, forgery etc. He further advised them to maintain good personal and environmental hygiene and observe and respect the customs, cultures and traditions of the host communities. Finally, he assured parents that University Management will do her best to give their children and wards quality training and comprehensive education as encapsulated in the institutional philosophy."],["p","In his remarks, the Governor of Imo State and Visitor emphasized that KOMU is a major investment owned wholly by Imo State. He said that the government was interested to make KOMU an exceptional university and urged management to develop strategies for early self-sustenance. He commended Management for great strives achieved within a short period of time especially the stability in the academic calendar that will guarantee timely graduation of students and the successful accreditation of 11 programmes by the National Universities Commission (NUC)."],["p","He further advised students to respect the host communities and urged staff to act as “in loco parentis” and teach and educate the students as their own children. He congratulated the students and urged them to abhor all anti-social vices, eschew violence, be agents of peace and be the best they can be emphasizing that their parents and society and Imo State are waiting for them to finish and contribute their quota to their family, state, and nation-building."],["p","A total of 120 students in four faculties received the matriculation oath. The event was witnessed by members of the Senate, the Hon. Commissioner for Education, Professor S.I. Okorondu, SA to the Governor on Education Programmes Intervention, Mrs. Esther Ukachukwu, three visiting Vice-Chancellors, and a host of other dignitaries."]]},{"id":31,"cat":"Leadership","date":"2022-06-13","title":"Faculty of Biological Sciences, UNN Honours Prof. Dozie, VC KOMU with Distinguished Alumnus Award","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-Chancellor of Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State Professor Ikechukwu Nosike Simplicius Dozie was on Wednesday, the 8th of June, 2022 honoured with the Distinguished Alumnus Award of…","body":[["p","The Vice-Chancellor of Kingsley Ozumba Mbadiwe University (KOMU), Ideato, Imo State Professor Ikechukwu Nosike Simplicius Dozie was on Wednesday, the 8th of June, 2022 honoured with the Distinguished Alumnus Award of the University of Nigeria Nsukka (UNN). The event took place during the Maiden Homecoming of the Faculty of Biological Sciences."],["p","The Vice-Chancellor and his team were warmly received at Lion's Building by the Chief Host and Vice-Chancellor of UNN, Professor Charles Igwe. During the courtesy call, Professor Dozie conveyed the warm felicitations of the Governor of Imo State and Visitor to KO Mbadiwe University, His Excellency Senator Hope Uzodimma to the University of Nigeria community. He expressed happiness at visiting his alma mater once again and commended Prof. Igwe and his team for sustaining the culture of excellence and scholarship that UNN is renowned for. In his response, Professor Charles Igwe, ably represented by the DVC Administration, Prof. Patrick Okpoko, expressed his happiness that one of her alumni now heads the 2nd State University in Imo State Nigeria. He pledged that UNN would find ways to support and collaborate with Prof. Dozie in building the young university."],["p","During the homecoming event, Prof. Dozie delivered the Keynote address entitled, “The Alumni – an untapped resource in the Nigerian University system”. One of the high points of the ceremony was the conferment of the Distinguished Alumnus Award on Prof. Dozie in recognition of his accomplishments in the areas of academic/research and administration."],["p","Another high point of the ceremony was the commissioning of the newly landscaped car park at the back of the Faculty of Biological Sciences block called the JIMBAZ building as well as the planting of a tree in commemoration of the World’s Environment Day Celebration all performed by Prof. Dozie on behalf of the other alumni present at the occasion."],["p","Dignitaries at the event included Prof. Bartho Okolo, former Vice-Chancellor of UNN and Chairman of the occasion; Prof. Johnson Urama, DVC Academic; Barr. Dr. Christopher Igbokwe, Registrar; Professor Polycarp Chigbu, former DVC (Academic) UNN; Prof. Florence Akaneme, Dean Faculty of Biological Sciences; Deans of Faculties; Directors of Institutes; Heads of Departments; Professors and members of the Faculty of Science Academic Board, Alumni and students of UNN."],["p","Ekene Bob-Ekechukwu Esq"],["p","Public Relations Officer"]]},{"id":30,"cat":"Academics","date":"2022-05-21","title":"KOMU Set for her 4th Matriculation Ceremony","by":"","img":null,"sum":"","body":[]},{"id":29,"cat":"Partnerships","date":"2022-05-19","title":"KO Mbadiwe University: NCC Donates 100 E-Pads and Digital Bridge Institute (DBI) Trains 100 Staff on Digital Literacy Skills","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Nigerian Communication Commission (NCC) has donated 100 e-pads and associated accessories to Kingsley Ozumba Mbadiwe University Ideato. In a letter to the Vice-Chancellor, Professor I.N.S. Dozie, under reference:…","body":[["p","The Nigerian Communication Commission (NCC) has donated 100 e-pads and associated accessories to Kingsley Ozumba Mbadiwe University Ideato. In a letter to the Vice-Chancellor, Professor I.N.S. Dozie, under reference: NCC/PD/SIP/OA/09/21/028 dated December 14, 2021, Professor Umar Danbatta, Executive Chairman/CEO Nigerian Communication Commission wrote that the donation was made under the Commission’s Digital Economy/Advanced Digital Appreciation Programme for Tertiary Institutions (ADAPTI) aimed at improving the digital skills of staff and students of the institution to contribute their quota in the emerging Nigerian digital economy."],["p","In a related Development, the Digital Bridge Institute (DBI), a subsidiary of the Nigerian Communication Commission has trained 100 staff of the institution on basic ICT Office productivity tools, including the intranet, internet, use of e-teaching and e-learning facilities, etc. The 5-day training commenced on Tuesday, May 10, 2022. It is notable that the University in the discharge of her Corporate Social Responsibility (CSR) to the host communities included 20 graduate participants drawn from the five (5) host communities of Ogboko, Umuchima, Obioha, Umuesi and Oguma to benefit from the training. This training was aimed at improving ICT skills of staff thus enabling them to translate the acquired knowledge and skills into improved teaching and work performance."],["p","The Vice-Chancellor, Professor I.N.S. Dozie had on behalf of the Governor of Imo State and Visitor to the University His Excellency Senator Hope Uzodimma, Senate, Staff and Students of the institution expressed deep appreciation to NCC and DBI for their kind gestures to the young institution. He has also appealed to Imo citizens and other Nigerians to support the efforts of the government through various donations aimed at improving the instructional and physical facilities in the institution."],["p","SUBSECTION OF PARTICIPANTS AT THE DBI TRAINING"]]},{"id":28,"cat":"Academics","date":"2022-05-05","title":"Accreditation of Academic Programmes in K.O Mbadiwe University","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The National Universities Commission (NUC) has accredited eleven (11) academic programmes at the Kingsley Ozumba Mbadiwe University (KOMU). The University scored a 100% in the programmes presented for accreditation.…","body":[["p","The National Universities Commission (NUC) has accredited eleven (11) academic programmes at the Kingsley Ozumba Mbadiwe University (KOMU). The University scored a 100% in the programmes presented for accreditation. Eight (8) of the programmes were granted full status, while the remaining three (3) were granted interim status."],["p","The list of the accredited programmes is as follows:"],["p","Administration"],["p","1. Accounting - Full"],["p","2. Business Administration - Full"],["p","Arts"],["p","1. English and Literary Studies - Full"],["p","2. History and International Relations - Full"],["p","Computing"],["p","1. Computer Science - Interim"],["p","Science"],["p","1. Biochemistry - Full"],["p","2. Microbiology - Full"],["p","Social Science"],["p","1. Economics - Interim"],["p","2. Political Science - Full"],["p","3. Psychology - Full"],["p","4. Sociology - Interim"],["p","This great feat was achieved with the massive support of the University Visitor, His Excellency, Sen. Hope Odidika Uzodinma. Who in line with the 3R programme of his administration, has given special attention to the education sector."],["p","In addition, the appointment of Prof Ikechukwu Nosike Simplicius Dozie as Vice-Chancellor has proven to be akin to placing a round peg in a round hole. The Vice-Chancellor ever since he assumed office, with his management team, has placed the University on the path to greatness. It is expected that more academic programmes will be accredited shortly to enable the University to deliver quality education in line with its core mandate. To God be all the glory and honour."],["p","Ekene Bob-Ekechukwu Esq"],["p","University Public Relations Officer"]]},{"id":26,"cat":"Partnerships","date":"2022-04-19","title":"KOMU Vice-Chancellor Professor Dozie Lauds OWSD","by":"","img":null,"sum":"The Vice-Chancellor, Kingsley Ozumba Mbadiwe University Ideato, Professor I. N. S. Dozie has extolled members of the Organisation for Women in Science for the Developing World (OWSD) for finding it worthy to inaugurate…","body":[["p","The Vice-Chancellor, Kingsley Ozumba Mbadiwe University Ideato, Professor I. N. S. Dozie has extolled members of the Organisation for Women in Science for the Developing World (OWSD) for finding it worthy to inaugurate their local chapter in the university, marking the first of its kind since he assumed office as Vice-Chancellor. While receiving the Leadership of the Organisation on April 7, 2022, who were on a courtesy visit to his office, the Vice-Chancellor said women play a very important role in society. He made reference to Margaret Thatcher's quote; \"If you want something said, you ask a man. If you want something done, you ask a woman\". VC said as long as there are lots of cultural differences and inequalities hindering women from attaining full potential, there is need to work collectively as Government on one hand and as stakeholders on the other hand for women to achieve their full potential, especially in the areas of science, technology, engineering, and mathematics. KOMU Chief Executive added that KO Mbadiwe University being gender-sensitive in its policy appointed women into key positions like; University Librarian, Dean of the Faculty of Arts, Acting Director General Studies, Admissions Officer, Student Affairs officer, and other important positions. The Vice-Chancellor appealed to his visitors to help in projecting the good image of the University and also informed them that the University Admission is currently ongoing."],["p","The leader of OWSD delegation, Dr. Nkeiru Kamalu earlier said they were at the Vice-Chancellor's office to inform him of the inauguration of the OWSD, KOMU Chapter and to thank him for his support to the Organisation. At the Senate Chambers where the ceremony took place thereafter, the Vice-Chancellor was represented by the Deputy Vice-Chancellor, Professor Aloy Onyeka who was also the Chairman of the occasion."],["p","The Chief Guest of Honour, Dr. Mrs C. P Dozie, wife of the Vice-Chancellor and Acting Director of the Directorate of General Studies read out the VC's Address. The high point of the Occasion was the decoration of Vice-Chancellor as SCIENCE AMBASSADOR by ORGANISATION FOR WOMEN IN SCIENCE FOR DEVELOPING WORLD, OWSD. The Award, which was received by Dr. C. P Dozie on her husband’s behalf was presented by OWSD National President, Professor Olanyika Ibiwumi Nwachukwu. Prof. Nwachukwu was represented by the South-East OWSD President, Professor Nkeiru Orji"],["p","Story by"],["p","Amb. Hippo Anyaehie Nwachukwu"],["p","Information and Public Relations Unit"]]},{"id":25,"cat":"Leadership","date":"2022-04-19","title":"K.O Mbadiwe University's VC Makes Case for Gender Equality","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-Chancellor of Kingsley Ozumba Mbadiwe University, Ideato, Prof. Ikechukwu Simplicius Nosike Dozie has made a case for gender equality and more inclusion of women in national affairs. He made this call at the…","body":[["p","The Vice-Chancellor of Kingsley Ozumba Mbadiwe University, Ideato, Prof. Ikechukwu Simplicius Nosike Dozie has made a case for gender equality and more inclusion of women in national affairs. He made this call at the inauguration ceremony of the Stand-Up for Women Society (SWS) Nigeria held on Thursday, the 24th day of March 2022, at Haven Suites, World Bank Housing Estate, Owerri."],["p","Prof. Dozie who was represented at the occasion by the Acting Director of General Studies of the University, Dr. Mrs. Patricia Chinomso Dozie, stated in his opening remarks, that the theme of the programme, \"Women: Bridge Builders\", was timely taking into consideration the recent rejection of about five (5) gender equality bills that sought to alter the Constitution by the National Assembly."],["p","He pointed out that the decision of the National Assembly to reject the gender equality bills engendered criticisms and even protests by women as well as civil society groups. Stressing that women are multi-talented and indispensable elements who require both the support of the society and government to actualize their individual dreams."],["p","Furthermore, he encouraged women to be bold and never allow the multifaceted and socially induced limitations evident around them to hold them back from succeeding in their careers, callings and natural roles as mothers and wives. Also, he advised women to look up to God and invest more time in developing themselves by reading inspirational kinds of literature. In addition, he counselled them to join social groups such as the Stand-Up for Women Society, that can bring out the best in them."],["p","In conclusion, the Vice-Chancellor, called on both men and women to live harmoniously, respecting individual roles and supporting one another to achieve full potential in life. He called on the National Assembly to reconsider passing the five (5) gender equality bills into law. Opining that it will further strengthen the roles of women as bridge builders in the society and the country at large."],["p","Ekene Bob-Ekechukwu Esq"],["p","Public Relations Officer"],["p","K.O. Mbadiwe University,"],["p","Ogboko, Imo State"]]},{"id":24,"cat":"Leadership","date":"2022-04-01","title":"K.O Mbadiwe University Conducts Staff Recruitment Interview","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Kingsley Ozumba Mbadiwe University, Ogboko, Ideato North Local Government Area, Imo State, commenced its staff recruitment interview on Wednesday, the 30th day of March 2022. The exercise which is expected to last…","body":[["p","The Kingsley Ozumba Mbadiwe University, Ogboko, Ideato North Local Government Area, Imo State, commenced its staff recruitment interview on Wednesday, the 30th day of March 2022. The exercise which is expected to last for two weeks is taking place at the campus of the university."],["p","The interview which is for the recruitment of various cadres of teaching staff, has over four hundred (400) shortlisted candidates interviewed for the rank of Assistant Lecturer and Lecturer II. Candidates with doctorate degrees and professorships will be interviewed in batches ranging from 16 to 30. The exercise is meant to boost the staff strength of the university. This is in line with the 3R programme of His Excellency, Sen. Hope Uzodinma to create more jobs in the State."],["p","It may be recalled that the university lacked adequate staff strength until the advent of the performing governor, Sen. Uzodinma. With this exercise, the staff strength of the university will be enhanced to actualize its core mandate which is the delivery of quality education of international standard."],["p","Based on the foregoing, it is apparent that the management of the university ably led by the indefatigable and amiable Vice-Chancellor, Prof Ikechukwu Simplicius Nosike Dozie has set the university on the path to success. With this tempo, It is expected that in no distant time, the institution will be placed on the list of top universities both in Nigeria and abroad."],["p","Ekene Bob-Ekechukwu Esq."],["p","Public Relations Officer"],["p","K.O. Mbadiwe University,"],["p","Ogboko."]]},{"id":23,"cat":"Academics","date":"2022-03-17","title":"KOMU Library Snack and Chat","by":"","img":null,"sum":"Kingsley Ozumba Mbadiwe University (KOMU) Library “SNACK AND CHAT”was an interactive time out with our students, faculty and other staff members on Valentine’s Day. It was an opportunity to showcase our services while…","body":[["p","Kingsley Ozumba Mbadiwe University (KOMU) Library “SNACK AND CHAT”was an interactive time out with our students, faculty and other staff members on Valentine’s Day. It was an opportunity to showcase our services while acquainting our staff members and students with resources available for their research and assignments. The account of historians about February 14 has it that St. Valentine a priest and legend is associated with a beautiful story of love, a story of hope, an inspiration, a fancy story of affection, and a story of devotion."],["p","Consequently, KOMU Library took advantage of this beautiful Valentine’s Day to put students and staff members in the know that our library resources, facilities and services are such that are devoted to be insightful and impactful on their path to self-development and achievements, this informal gathering was also an opportunity to show that love and knowledge are the keys to being all that we are intended to be."],["p","There were quizzes and KOMU branded prices given out to outstanding students as well as to “KOMU LIBRARY LOVERS”."],["p","#Light music and Snack"],["p","#Quizzes"],["p","#Library lovers"],["p","#Dancing competition"],["p","A Cross-section of Student and Staff at the Event"]]},{"id":22,"cat":"Admissions","date":"2022-02-04","title":"Offer of Supplementary Admission Spaces","by":"Ernest Onuoha","img":null,"sum":"Kingsley Ozumba Mbadiwe University offers supplementary admission into its regular undergraduate programmes to qualified candidates (with score of 120 and above in UTME) in the ongoing 2021/2022 admission exercise","body":[["p","KINGSLEY OZUMBA MBADIWE UNIVERSITY"],["p","IDEATO, IMO STATE"],["p","ADMISSION FOR 2021/2022 SESSION"],["p","ADMISSION! ADMISSION! ADMISSION!"],["p","Kingsley Ozumba Mbadiwe University offers supplementary admission into its regular undergraduate programmes to qualified candidates (with score of 120 and above in UTME) in the ongoing 2021/2022 admission exercise"],["p","AVAILABLE COURSES:"],["p","Faculty of Sciences:"],["li","Biochemistry (B.Sc.)"],["li","Microbiology (B.Sc)"],["li","Zoology (B.Sc)"],["li","Computer Science (B.Sc)"],["li","Botany (B.Sc)"],["li","Physics (B.Sc)"],["li","Chemistry (B.Sc)"],["li","Biology (B.Sc)"],["li","Mathematics (B.Sc)"],["li","Statistics (B.Sc)"],["p","Faculty of Management Sciences:"],["li","Accounting (B.Sc)"],["li","Business Administration (B.Sc)"],["li","Banking & Finance (B.Sc)"],["li","Economics (B.Sc)"],["li","Political Science (B.Sc)"],["li","Sociology (B.Sc)"],["li","Psychology (B.Sc)"],["li","Management (B.Sc)"],["p","Faculty of Arts:"],["li","English Language & Literary Studies (B.A)"],["li","History & International Studies (B.A)"],["li","Linguistics (B.A)"],["p","Faculty of Environmental Sciences:"],["li","Architecture (B.Sc)"],["li","Estate Management (B.Sc)"],["p","HOW TO APPLY"],["p","Interested candidates should strictly follow the under-listed steps to be considered for admission."],["p","Ø Change your University of first choice to Kingsley Ozumba Mbadiwe University on JAMB portal"],["p","Ø Upload your O’level results in JAMB CAPS."],["p","Ø Visit the KOMU website at www.komu.edu.ng; Click on Start the application process; fill out the form completely and Submit."],["p","Screening of already admitted candidates holds at the University Campus at Ogboko on the following days:"],["p","Ø Thursday, 3rd February 2022"],["p","Ø Friday 4th February 2022"],["p","Ø Tuesday 8th February 2022 (Last Day)"],["p","Hurry while the offer lasts!!"],["p","For further inquiries please call the Admissions Officer on 08034646192 or visit the KOMU website at www.komu.edu.ng for details."],["p","O.E. Onuoha"],["p","Registrar"]]},{"id":21,"cat":"Academics","date":"2022-02-02","title":"NUC Visits Kingsley Ozumba (KO) Mbadiwe University (KOMU) Ideato on Maiden Accreditation of Academic Programmes","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The National Universities Commission (NUC) in the discharge of her statutory regulatory function of ensuring compliance with the quality of undergraduate programmes in Nigerian Universities visited KO Mbadiwe University…","body":[["p","The National Universities Commission (NUC) in the discharge of her statutory regulatory function of ensuring compliance with the quality of undergraduate programmes in Nigerian Universities visited KO Mbadiwe University Ideato for her maiden accreditation exercise which took place between Thursday, January 27 and Saturday, January 29, 2022. The 44-man NUC Team examined eleven (11) academic programmes in the University comprising; Biochemistry, Microbiology and Computer Science in the Faculty of Science; English and Literary Studies and History and International Studies in the Faculty of Arts as well as Psychology, Sociology, Political Science, Economics, Business Administration and Accounting in the Faculty of Social and Management Sciences."],["p","In a chat with our reporter, the Vice-Chancellor Professor I.N.S. Dozie expressed deep gratitude to God for the success of the exercise, despite the challenges associated with the transition to KO Mbadiwe University and the short time interval for preparation. He appreciated the Visitor to the University and Governor of Imo State, His Excellency Senator Hope Uzodimma for his firm and generous support for the accreditation exercise as well as the steady growth and development of the university. He also appreciated the Management, Staff, and Students of the institution for their deep commitment before and during the exercise."],["p","The VC informed our reporter that the university like other institutions that had their accreditation exercises will wait for the result of the exercise which will be released by NUC in due course."],["p","Furthermore, the Vice-Chancellor hinted that admission exercise is still ongoing in the University. The minimum pass mark for the Supplementary Admission exercise is 120 marks for the 23 programmes offered in the 2021/2022 academic session."]]},{"id":20,"cat":"Admissions","date":"2022-01-14","title":"Admission! Admission!! Admission!!!","by":"Rejoice N. Adioha","img":null,"sum":"2026/2027 KOMU POST-UTME AND DIRECT ENTRY SCREENING EXERCISE KOMU invites candidates with UTME scores of 150 and above, who desire admission into its NUC-approved undergraduate academic programmes for the 2026/2027…","body":[["p","2026/2027 KOMU POST-UTME AND DIRECT ENTRY SCREENING EXERCISE KOMU invites candidates with UTME scores of 150 and above, who desire admission into its NUC-approved undergraduate academic programmes for the 2026/2027 academic session, from Monday, 01/06/2026"],["p","Candidates who did not originally choose KOMU as their first choice institution would also be considered for admission into programmes requiring a minimum JAMB Score of 150 if they change their institution of first choice to KOMU on the JAMB Central Admission Processing System (CAPS)"],["p","Candidates who scored below 150 or want to study Nursing, Medicine, Law or Medlab Science but did not originally make KOMU First Choice during registration can apply for our JUPEB or IJMB Programme"]]},{"id":19,"cat":"Admissions","date":"2021-12-08","title":"Students' Portal Now Open for Payment of Fees","by":"","img":null,"sum":"","body":[["p","PROCEDURES FOR PAYMENT OF SCHOOL FEES"],["p","ON KOMU WEBSITE: www.komu.edu.ng"],["li","Go to KOMU website: www.komu.edu.ng"],["li","Click on ACADEMIC PORTAL from the navigation menu"],["li","Click on the STUDENT PORTAL link"],["li","Enter your JAMB REG.NO as both your LOGIN ID and PASSWORD"],["li","Click on SIGN ME IN"],["li","Confirm that your displayed NAME, LEVEL, DEPARTMENT and FACULTY are all correct. If not correctly displayed, report to ICT Centre and do not proceed to make payment."],["li","Click on MAKE NEW PAYMENT from the navigation menu"],["li","Click on the PROCEED TO PAY button"],["li","The exact amount to be paid will be displayed. Confirm this by clicking on the MAKE PAYMENT button"],["li","The page that loads gives you a summary of the transaction including the transaction reference. You are advised to print this page for reference purpose by clicking on the PRINT button, before proceeding to click on the PAY NOW button"],["li","You will then be redirected to the Remita payment platform. Click on the SUBMIT button and select the most convenient of the eight (8) payment options available, including paying at a Bank Branch, your ATM Card, USSD, or even your Bank Account number, etc. and follow the instructions displayed for your preferred payment option."],["p","Thank you!"],["p","Mr. Wilson Agbarakwe"],["p","Ag. Bursar, KOMU"]]},{"id":18,"cat":"Academics","date":"2021-11-28","title":"Academic Staff Vacancies","by":"","img":null,"sum":"Applications are invited from suitably qualified candidates to fill vacancies in the indicated Academic Departments of the Kingsley Ozumba (KO) Mbadiwe University Ogboko, Imo State (formerly Eastern Palm University Ogboko).","body":[["p","Applications are invited from suitably qualified candidates to fill vacancies in the indicated Academic Departments of the Kingsley Ozumba (KO) Mbadiwe University Ogboko, Imo State (formerly Eastern Palm University Ogboko)."],["p","POSITIONS SALARY SCALE"],["p","i) Professor CONUASS 7"],["p","ii) Reader CONUASS 6"],["p","iii) Senior Lecturer CONUASS 5"],["p","iv) Lecturer I / Librarian I CONUASS 4"],["p","v) Lecturer II / Librarian II CONUASS 3"],["p","vi) Assistant Lecturer CONUASS 2"],["p","The vacancies are available in the following Faculties and Departments"],["p","A) Faculty of Science"],["p","Departments:"],["li","Microbiology"],["li","Biochemistry"],["li","Zoology"],["li","Mathematics"],["li","Computer Science"],["li","Statistics"],["li","Chemistry"],["li","Physics"],["li","Biology"],["p","B) Faculty of Social & Management Sciences"],["p","Departments"],["li","Accounting"],["li","Business Administration"],["li","Banking & Finance"],["li","Economics"],["li","Political Science"],["li","Psychology"],["li","Sociology"],["li","Business Management"],["p","C) Faculty of Arts"],["li","English & Literary Studies"],["li","History & International Studies"],["li","Linguistics"],["p","D) Faculty of Environmental Sciences"],["li","Architecture"],["li","Estate Management"],["p","Qualifications and Experience"],["p","i. Professor:"],["p","Applicants should possess a doctorate degree in the relevant field plus a minimum of twelve (12) years post qualification experience in teaching and research in a University. Demonstrate ability to initiate, develop and supervise research, capacity for academic leadership and a good record of scholarly publications and registration with relevant professional bodies where necessary."],["p","ii. Reader:"],["p","Applicants should possess a doctorate degree in the relevant field plus a minimum of ten (10) years post qualification experience in teaching and research in a university. Demonstrate ability to initiate, develop and supervise research, capacity for academic leadership and a good record of scholarly publications and registration with relevant professional bodies where necessary."],["p","iii. Senior Lecturer:"],["p","Applicants should possess a doctorate degree in the relevant field plus a minimum of six (6) years of teaching and research in a University. Industrial experiences as well as scholarly publication in reputable journals."],["p","iv. Lecturer I / Librarian I:"],["p","Applicants should possess postgraduate (preferably doctorate) degree in the relevant field plus three (3) years as Lecturer II."],["p","v. Lecturer II / Librarian II:"],["p","Applicants should possess doctorate degree or Master’s degree plus three (3) years as Assistant Lecturer."],["p","vi. Assistant Lecturer:"],["p","Applicants must have a Master’s degree in the relevant field."],["p","Method of Application"],["p","Interested candidates are requested to submit ten (10) copies of their application and detailed Curriculum Vitae in the following order:"],["li","Name in full (Surname first in capital letters)"],["li","Place and Date of Birth"],["li","Home Address"],["li","Postal Address"],["li","Telephone Number"],["li","Nationality/State of Origin"],["li","Marital Status"],["li","Number and Ages of Children"],["li","Institutions Attended (with dates)"],["li","Academic and Professional Qualifications (including distinctions with dates)"],["li","Names and Addresses of three (3) Referees"],["p","Position applied for should be clearly stated on the left hand side of the envelope"],["p","In addition to stating the names of referees, applicants should request their referees to forward references on their behalf under confidential cover direct to the Registrar. All applications must reach the address below not later than two (2) weeks from the date of this publication:"],["p","The Registrar"],["p","Kingsley Ozumba Mbadiwe University"],["p","P.M.B. 006"],["p","Orlu, Imo State"],["p","Nigeria."],["p","Please note that this publication was first published on November 22, 2021. Also, only shortlisted candidates will be contacted/invited for interview."]]},{"id":17,"cat":"Leadership","date":"2021-11-24","title":"KOMU News","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-chancellor, Professor Ikechukwu Nosike Simplicius Dozie, his wife, Dr Mrs Chinonso Patricia Dozie, other family members, DVC, Professor Aloy Onyeka, other Principal Officers, Staff, Students and Friends of KO…","body":[["p","The Vice-chancellor, Professor Ikechukwu Nosike Simplicius Dozie, his wife, Dr Mrs Chinonso Patricia Dozie, other family members, DVC, Professor Aloy Onyeka, other Principal Officers, Staff, Students and Friends of KO Mbadiwe University, KOMU were on Friday November 19 2021 in a solemn appearance participated in the first KOMU Ecumenical Thanksgiving Service that took place at the University's Senate Chamber."],["p","A high point of the event was unveiling of the Vice-chancellor's Eleven Point Strategic Goals toward accelerating progress of the University to a World-Class Status."],["p","The Thanksgiving Service was conducted by seven Officiating Priests who prayed for His Excellency, Distinguished Senator Hope Uzodimma, the Executive Governor Imo State, VC and his family, Principal Officers, Staff, Students, Host Communities and Friends of KOMU."],["p","In his note of appreciation, Professor Dozie who spoke of his least expectation that one day he would be appointed Vice-Chancellor KOMU, eulogized the Visitor to the University for finding him worthy to serve. He also thanked his wife, DVC, Registrar other Staff for supporting him as he celebrated six months anniversary as the University Vice-Chancellor KOMU."],["p","Cross-Section of Students and Staff of K.O. Mbadiwe University"],["p","The Priest Prays for the Visitor, H.E. Hope Uzodinma; The Vice-Chancellor and Family"],["p","//Hippo Anyaehie Nwachukwu"],["p","Ag. PRO KOMU."]]},{"id":16,"cat":"Admissions","date":"2021-11-08","title":"Admission into the Undergraduate Academic Programmes of Kingsley Ozumba Mbadiwe University (KOMU)","by":"Ernest Onuoha","img":null,"sum":"KOMU invites qualified candidates, who desire admission into its NUC approved undergraduate academic programmes for the 2021/2022 academic session.","body":[["p","KOMU invites qualified candidates, who desire admission into its NUC approved undergraduate academic programmes for the 2021/2022 academic session."],["p","AVAILABLE COURSES:"],["p","The available courses include:"],["p","FACULTY OF SCIENCE: Biochemistry, Microbiology, Zoology, Computer Science, Physics, Chemistry, Biology, Mathematics, Statistics"],["p","FACULTY OF SOCIAL & MANAGEMENT SCIENCES: Accounting, Business Administration, Banking & Finance, Economics, Political Science, Sociology, Psychology, Management"],["p","FACULTY OF ARTS: English Language & Literary Studies, History & International Studies and Linguistics"],["p","FACULTY OF ENVIRONMENTAL SCIENCES: Estate Management and Architecture"],["p","QUALIFICATION:"],["p","To qualify for admission into KOMU undergraduate programmes, prospective candidates must have sat for the 2021 UTME, irrespective of whether or not the candidates chose KOMU as their first choice of institution. However, candidates who did not choose KOMU as their first choice of institution are to effect change of institution on JAMB website. The required minimum UTME score is 120."],["p","Furthermore, Direct Entry candidates, who possess any of A/levels, NCE, ND, HND, Degree certificates in relevant subjects/disciplines are also qualified to apply."],["p","POST-UTME SCREENING FEE"],["p","The fee for KOMU Post-UTME screening is Two Thousand Naira (₦2000) only. All payments should be made using the Remita payment gateway."],["p","HOW TO APPLY FOR KOMU POST-UTME SCREENING EXERCISE"],["li","Visit the KOMU website at www.komu.edu.ng"],["li","Click on “Online Application”"],["li","Click on “Apply Online” and read the instructions"],["li","Click on “Start your Admission Process”"],["li","Click on “Start Application Process”"],["li","Fill out the form completely and correctly"],["li","Click on the Submit"],["li","You will be directed to pay the Post-UTME/Direct Entry application fee of N2000 only."],["li","Pay online with your Card or use any of the other available Remita payment options convenient for you."],["li","Print the Acknowledgement slip, which is also sent to your email"],["li","Bring your Acknowledgement slip to the University on the Post-UTME screening day."],["p","The Application Portal opens Monday, 8th November, 2021 and closes Wednesday, 8th December, 2021"],["p","Signed:"],["p","ERNEST ONUOHA"],["p","Registrar, KOMU"],["p","For further enquiries, please contact: 08034646192. Thank you!"]]},{"id":15,"cat":"Academics","date":"2021-11-05","title":"NUC Names 198 Federal, State & Private Universities in Nigeria. List KOMU as 42nd State University","by":"Obinna I Anyanwu","img":null,"sum":"The National Universities Commission (NUC) has provided a list of all federal, state, and private universities.","body":[["p","The National Universities Commission (NUC) has provided a list of all federal, state, and private universities."],["p","This is contained in its October bulletin which chronicled the commission’s activities."],["p","NUC had promised to keep Nigerians abreast of approved universities so that they do not fall for scammers and other unscrupulous elements. The country has a number of illegal tertiary institutions swindling uninformed citizens with the claim of running accredited courses. In the breakdown, there are currently 45 federal universities, 54 in states and 99 private, a total of 198."],["p","Meanwhile, NUC Executive Secretary, Prof Abubakar Rasheed has met with Vice-Chancellors and Sustainable Procurement, Environment and Social Standards Enhancement (SPESSE) Centre Leaders."],["p","The World Bank Project has a span of five years with an $80million budget. It seeks to institutionalise the procurement, environmental and social standards in Nigeria. While 37.5 percent has been earmarked for technical assistance, 62.5 percent would be disbursed based on performance using Disbursement Link Indicators (DLI)."],["p","Six tertiary institutions will run courses for the project that will benefit 25,240 candidates."],["p","They are the University of Lagos, Federal University of Technology Owerri, University of Benin, Ahmadu Bello University Zaria, Federal University of Agriculture Makurdi, and Abubakar Tafawa Balewa University Bauchi."],["p","The list of approved 198 Nigerian Universities:"],["p","Source: https://dailypost.ng/2021/11/02/nuc-names-198-federal-state-private-universities-in-nigeria-full-list/"]]},{"id":14,"cat":"Academics","date":"2021-11-03","title":"NUC visits K.O. Mbadiwe University Ogboko to Assess Students’ Support Facilities and Services","by":"","img":null,"sum":"A three (3) man team from the National Universities Commission (NUC) on Wednesday, October 21, 2021 paid a working visit to Kingsley Ozumba (KO) Mbadiwe University (KOMU) Ogboko in discharge of her statutory functions…","body":[["p","A three (3) man team from the National Universities Commission (NUC) on Wednesday, October 21, 2021 paid a working visit to Kingsley Ozumba (KO) Mbadiwe University (KOMU) Ogboko in discharge of her statutory functions as the apex Regulatory Agency."],["p","In her speech during the courtesy call on University Management, the Team Leader, Prof. Abigail Osuafor disclosed that the purpose of the visit was to evaluate Students Support Facilities and Services of the University. The exercise according to her was in line with the efforts of NUC to encourage and ensure continuous improvement in the performance and compliance of all Universities to NUC’s guidelines on the provision of quality support facilities and services for students in Nigerian Universities."],["p","The team was expected to assess the following facilities and support services, Campus environment, Accommodation in halls of residence, Admissions, Examinations and Release of Results, Library Services and Health Services."],["p","In his welcome response, the Vice Chancellor, Prof. Ikechukwu N.S Dozie on behalf of the Visitor, Governor Hope Uzodimma, Staff and Students of KO Mbadiwe University welcomed the Team to the University. He commended the Executive Secretary of NUC, Professor Abubakar Rasheed on his firm commitment towards the discharge of the regulatory functions of the Commission and expressed deep gratitude to the recognition accorded KO Mbadiwe University as the 42nd State University in Nigeria and 143rd in the Nigerian University System. He described the visit as a very welcome development underscoring the recent recognition of KO Mbadiwe University by NUC and assured them of maximum cooperation by Management in the conduct of the assessment exercise."],["p","The Vice Chancellor further reiterated that this visit was in line with his determination to drive the accelerated transformation of K.O Mbadiwe University to a world class institution as envisioned by his Eleven (11) Point Strategic Goals of Action which addresses holistically all aspects of University endeavour including the welfare and wellbeing of students."],["p","The University Registrar and Librarian, Conducting the NUC Team Around the Library"],["p","Prof Dozie commended the Governor and Visitor to the University, His Excellency Senator Hope Uzodimma for unstinted support to the university and the Management Team for working hard to prepare the University for the NUC Assessment Visit. Finally, the Vice-Chancellor assured the NUC Team that the University will correct any deficiencies associated with the assessment of Students Support Facilities and Services."]]},{"id":13,"cat":"Admissions","date":"2021-11-02","title":"Public Notice","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Management of Kingsley Ozumba (KO) Mbadiwe University, Imo State Nigeria has cancelled the 2020/21 academic session. The cancellation was due to issues related to the COVID-19 Pandemic which affected the timely…","body":[["p","KINGSLEY OZUMBA (KO) MBADIWE UNIVERSITY OGBOKO, IMO STATE CANCELS THE 2020/2021 ACADEMIC SESSION AND COMMENCES THE 2021/2022 ACADEMIC SESSION ON SEPTEMBER 27, 2021"],["p","The Management of Kingsley Ozumba (KO) Mbadiwe University, Imo State Nigeria has cancelled the 2020/21 academic session. The cancellation was due to issues related to the COVID-19 Pandemic which affected the timely completion of the 2019/2020 academic session and its consequent spillover effects on the commencement and successful conclusion of the 2020/2021 Session."],["p","Academic activities which were suspended due to the transition from the erstwhile Eastern Palm University to KO Mbadiwe University will now recommence in the 2021/2022 session."],["p","Old students are expected to return to Campus on Tuesday October 5, 2021 as several interventions on the University Campus environment and rehabilitation of many deteriorating physical facilities will have been completed. Admissions of new students will commence on September 30, 2021 as approved by the JAMB Policy meeting of August 31, 2021."],["p","Staff and Students will be required to observe strictly all COVID-19 protocol. In this respect, staff and students are expected to return with adequate face masks, face shields and hand sanitizers. Management will ensure provision of adequate water stations to encourage hand hygiene as well as social (physical) distancing in all University activities."],["p","Management assures the Government and good people of Imo State and indeed all Nigerians of her deep commitment to grow KO Mbadiwe University to be a World-Class University and consequently solicits the support of all stakeholders to achieve her overriding objective of training our children for self-actualization and for the task of nation building."],["p","Signed,"],["p","Management"]]},{"id":12,"cat":"Leadership","date":"2021-11-02","title":"KOMU recognized & listed on JAMB CAPS","by":"Ikechukwu Nosike Dozie","img":null,"sum":"The Vice-Chancellor of Kingsley Ozumba Mbadiwe University KOMU, Professor Ikechukwu N.S Dozie yesterday visited the SA to Governor Hope Uzodimma, Abuja Liason, Dr Jimmy Imo while on fact finding mission to JAMB.","body":[["p","The Vice-Chancellor of Kingsley Ozumba Mbadiwe University KOMU, Professor Ikechukwu N.S Dozie yesterday visited the SA to Governor Hope Uzodimma, Abuja Liason, Dr Jimmy Imo while on fact finding mission to JAMB."],["p","At JAMB Headquarters Abuja, the KOMU Chief Executive ensured that KOMU was listed and captured on JAMB CAPS for ease of online admissions."],["p","Having emberked on such visit severally in the past, the November first visit proved confirmatory and KOMU is now active on JAMB portal."],["p","The V.C. in a warm handshake with Dr. Jimmy"],["p","The Vice-Chancellor was accompanied on the visit by his Executive Assistant & Coordinator Vice-Chancellor's Office, Barr. Obinna Igwe."],["p","Hippo A Nwachukwu."],["p","Ag PRO KOMU."],["p","2nd Nov. 2021."]]},{"id":11,"cat":"Leadership","date":"2021-10-25","title":"Professor Onyeka, Now DVC Of KO Mbadiwe University,School Set To Advertize For New Intake","by":"","img":null,"sum":"In line with the determination of the Prof Ikechukwu Dozie led management of Kingsley Ozumba Mbadiwe University and that of the institution’s Visitor, Governor Hope Uzodinma, Prof Aloysius Chijioke Onyeka, a renowned…","body":[["p","In line with the determination of the Prof Ikechukwu Dozie led management of Kingsley Ozumba Mbadiwe University and that of the institution’s Visitor, Governor Hope Uzodinma, Prof Aloysius Chijioke Onyeka, a renowned academic, administrator and seasoned manager of men and resources, has been appointed, Deputy Vice Chancellor."],["p","Onyeka, a widely published Professor of Stastics with Specialty in Stastical Computing and Sample Surveys whose appointment has been ratified by the University’s Visitor, Governor Hope Uzodinma has already assumed duty."],["p","This is coming at a time that the University which was enmeshed in controversy over its ownership status has commenced activities for the 2021/2022 academic session and is about to advertize for new intake."],["p","Prof Aloysius Chijioke who hails from Okporo in Orlu LGA of Imo state, attended Ihitte-Akatta Primary School, Awka-Akatta, and Bishop Shanahan College, Orlu before proceeding to Imo state university, Uturu for his first degree. Thereafter, he attended the University of Ibadan for his Masters and Doctoral degree programs."],["p","Prof Onyeka, an astute University administrator has shown capacity and recorded monumental achievements over the years, in the areas of Statistical Analysis of Research Data, with over 80 successful PhD Thesis analysis, Productive Works in Statistical Computing, Advances in Information and Communication Technology (ICT), Sampling Theory and Survey Methodology and Consultancy/Human Capital Development."],["p","The new Deputy Vice Chancellor, has vast teaching, administrative and leadership experience, having occupied different positions, including, Pioneer Rector, Bishop Shanahan Polytechnic Orlu; Pioneer Head, Department of Statistics, Federal University of Technology (FUTO), Owerri;Head, Department of Computer Science, FUTO; Director Information and Communication Technology, Centre (FUTO); Director, University Computer Centre (UCC), FUTO; Sabbatical/Visiting Professor, Department of Statistics, Abia State University, Uturu. He also pioneered the use of Computer-based tests (CBT) in writing JAMB examination at FUTO among others."],["p","Prof Onyeka is Chief Consultant and Resource Person to the Imo state government on Computer Training and supply of computers to staff of Imo state Local Empowerment and Environmental Management Project (LEEMP), Chief Consultant and Resource Person to the Imo state government through the Imo state Public Sector Governance Reform and Development Project (World Bank Assisted) on training of staff of Imo State Bureau of Statistics on the use of SAS software and Pioneer Proprietor/CEO, Owerri CBT, Hi-Tech, Owerri, a JAMB approved CBT Centre and top notch digital learning outfit."],["p","The Orlu born academic and university administrator belongs to a number of national and international professional bodies, including International Statistical Institute (ISI), International Association of Survey Statisticians (IASS), International Biometric Society (IBS), Royal Statistical Society (RSS), Nigerian Statistical Association (NSA) and Professional Statisticians Society of Nigeria (PSSN)."]]},{"id":10,"cat":"Leadership","date":"2021-10-06","title":"The Vice-Chancellor Makes his Inaugural Address to the General Assembly","by":"","img":null,"sum":"It is with deep humility, sincere gratitude to God Almighty and a committed sense of responsibility that I address you today as the Vice-Chancellor of Kingsley Ozumba Mbadiwe University (KOMU), Ogboko, Ideato South LGA,…","body":[["p","AN ADDRESS BY THE VICE-CHANCELLOR, PROFESSOR IKECHUKWU NOSIKE SIMPLICIUS DOZIE TO THE MAIDEN GENERAL ASSEMBLY OF THE KINGSLEY OZUMBA MBADIWE UNIVERSITY (KOMU) OGBOKO, IMO STATE, NIGERIA ON 5TH OCTOBER, 2021."],["p","Principal Officers of the University"],["p","Deans and Directors"],["p","Members of the University Senate"],["p","Members of Congregation"],["p","Respected Staff and Students of the University"],["p","Distinguished Ladies and Gentlemen"],["p","INTRODUCTION"],["p","It is with deep humility, sincere gratitude to God Almighty and a committed sense of responsibility that I address you today as the Vice-Chancellor of Kingsley Ozumba Mbadiwe University (KOMU), Ogboko, Ideato South LGA, Imo State, Nigeria. I am happy to familiarize with you all as members of the University Community."],["p","Permit me to begin this address with a note of deep appreciation to His Excellency, Senator Hope Uzodimma, Governor of Imo State for finding me worthy to serve and consequently approved my appointment as Vice-Chancellor of this young but would be historic university. I wish to assure His Excellency once again, that I will remain committed and uphold the confidence associated with my appointment as Vice-Chancellor in the discharge of this responsibility. I am not unmindful of the challenges we face in growing KOMU to be an institution of repute and reckoning and a first choice destination for our teeming youths seeking world-class education and qualitative mentorship. I am confident that by the special grace of God and the assured support of government as well as various stakeholders, we shall succeed in our task. We will always support the “3-R Vision” of His Excellency aimed at the Rehabilitation, Reconstruction and Rebuilding of Imo State to be a model modern State through our activities in KOMU."],["p","PURPOSE OF A UNIVERSITY"],["p","The purpose of a university is to create knowledge through scholarship and research, transmit knowledge through instruction (i.e. teaching) and lastly, apply knowledge through public service. In other words, universities are created to satisfy specific or general educational needs of a nation through teaching of students, conduct of research and dissemination of knowledge together with other community activities. Therefore, the primary mission of the university is simply, teaching, research and community service."],["p","ESTABLISHMENT OF KOMU"],["p","As you are aware, KOMU came into existence through the enactment of the Kingsley Ozumba (KO) Mbadiwe University (Establishment) Law No. 1 of 2021 by the Imo State House of Assembly and assented to by His Excellency, Governor Hope Uzodimma on 18th February, 2021. This Law repealed the Eastern Palm University which was established in 2016 and recognized by the National Universities Commission (NUC) as the 42nd State University and 143rd in the Nigerian University System. Statutorily, Kingsley Ozumba University has replaced the defunct Eastern Palm University"],["p","The mandate of KOMU is, “to encourage the advancement of learning in Imo State in particular and Nigeria in general, to hold out to all persons without the distinction of race, creed or sex and to give them the opportunity of acquiring higher education in various fields of study”."],["p","The specific objectives of the university are to:"],["p","a. Provide a wide range of quality learning opportunities for undergraduate and postgraduate students without distinction of race, creed, sex, religion or political conviction that will enhance their best intellectual, social, economic and personal development;"],["p","b. Provide academic, professional and vocational training of high quality in a way as to enrich and improve the State, National, and International human resource capabilities and assist graduates to contribute to the common good of society;"],["p","c. Foster academic research, which contributes to human knowledge and the vitality of the institution;"],["p","d. Encourage thoughtful and responsible staff and student participation in Local, State, National and International affairs;"],["p","e. Maintain the highest academic standards in respect of University degrees and other awards and preserve and protect their reputation and integrity;"],["p","f. Evolve academic programmes to suit the changing social and economic needs of society through continuous review of curricula and development of new programmes to respond to societal and technological changes in Nigeria and the world in general and Imo State in particular;"],["p","g. Advance human culture and improve human life through the development, refinement and dissemination of knowledge and to prepare competent graduates to meet the development needs of Imo State in particular and Nigeria in general;"],["p","h. Relate its activities to the social, cultural and economic needs of the people of Imo State and Nigeria."],["p","Distinguished colleagues, the successful achievement of the objectives of establishment are clearly the task before us. It is significant that the Law establishing KOMU recognizes the sensitivities and semblance of the character of world-class universities namely qualitative teaching and mentorship, innovative and cutting edge research, knowledge transfer and international/global outlook."],["p","For more simplistic emphasis, we all are expected to build a university which in concept and operation is akin to a marketplace of ideas, diversity of thought, culture and perspectives, which are in conformity with the global character of leading universities. We all are expected to grow a university where the ethos of teamwork, respect, integrity, excellence, ethics, professionalism, equity, justice, inclusion, innovation and collaboration will characterize her style and sense of direction. Furthermore, we are expected to build a university with open door policy and governed by the time-tested Committee system which enhances the participation of everyone and which her leadership style leaves no one in doubt about her direction and trajectory for her future development to a world-class status."],["p","VISION, MISSION, PHILOSOPHY, CORE VALUES, MANTRA, MOTTO AND LOGO"],["p","Vision Statement"],["p","The vision of the Kingsley Ozumba University is to be a globally competitive institution renowned for innovative research and scholarship, world-class education and human resource development to address current and future needs of society."],["p","Mission Statement"],["p","The mission is to make KOMU famous for producing talented men and women with passion and skills to apply knowledge and technology sensibly to solve the problems of the nation and the global community at large."],["p","At the core of this mission is our firm desire to educate future leaders not just to acquire requisite knowledge and various life survival skills, but leaders with deep passion for humanity in the discharge of their civic responsibilities for the good of society i.e. “developing the complete man – soul, body and divinity”"],["p","Philosophy"],["p","In KOMU, we are driven by a strong determination to produce scholars who are loaded with triple capacity for success, global competitiveness and stardom anchored on our core values of integrity, excellence, team work, innovation and collaboration."],["p","Core Values"],["p","Our core values to drive our vision and actualize our mission will be anchored on integrity, excellence, team work, innovation and collaboration [IETIC]."],["p","§ Integrity: We shall strive to be honest, respectful, transparent, accountable, fair and equitable in our dealings"],["p","§ Excellence: We will ensure best practices, adopt meritocracy and apply the highest ethical standards in our activities inclusive of preserving the natural environment"],["p","§ Team work: We shall work closely and inclusively with each other and one another, communicating openly to achieve common goals"],["p","§ Innovation: We shall strive to be creative, harnessing our innate transformative energy for the good of the environment and the society in a responsible manner."],["p","§ Collaboration: We shall build viable and strong bonds of friendship with similar organizations for mutual benefit."],["p","Mantra"],["p","Our mantra will be: “Our university working as a team with one mission to render selfless service to humanity” a.k.a. “KOMU. One team. One mission. Selfless service to humanity”."],["p","Motto"],["p","Selfless Service to Humanity"],["p","Logo"],["p","The Logo is made up of a book, a graduation cap, and the globe with stars dotted around it, all housed by the name of the University. Beneath the name of the University is the Motto. The narrative is that the University as a hub of academic activity uses the book as a tool for learning to produce scholars who become stars around the globe."],["p","The colours of the University as shown in the Logo are black, blue and golden. Symbolically, the black colour represents the power and authority of Senate as the highest decision-making body to organize and control teaching, promote research as well as admission and discipline of students. The blue colour represents the sky as the limit for our staff and students in their quest for excellence and scholarship. The golden colour represents the wisdom and passion of members of our community in rendering selfless service to humanity."],["p","IMPLEMENTATION OF MY VISION AND MISSION"],["p","The strategy for implementation of my vision and mission for accelerated transformation of KOMU to a world class institution addresses holistically all aspects of university endeavour. These have been clearly integrated into an eleven (11) point strategic goal as follows:"],["p","1. Promoting Qualitative Teaching and Learning and Mentorship to achieve First Class Education and Graduate Output at undergraduate and postgraduate levels."],["p","2. Cultivating a Culture of Sustainable Innovative and Cutting-edge Research and Entrepreneurship Education to address societal problems."],["p","3. Mainstreaming Information and Communications Technology (ICT) for Digital Transformation and Efficient Service Delivery"],["p","4. Expanding Access with Innovative Programmes and Sustaining Existing Academic Programmes as well as Strengthening Academic Support Units for Improved Excellence."],["p","5. Providing Clean, Reliable and Steady Electricity and Strengthening other Municipal Services for Institutional Development."],["p","6. Improving Physical and Security Infrastructure and Promoting a Healthy, Safe and Aesthetic Environment for Conducive Education."],["p","7. Building Strategic Partnerships and Collaborations for Improved University Ranking and Overall Global Outlook"],["p","8. Creating Excellent Relationships with Staff and Student Unions, Alumni, Host Communities and various Stakeholders (State Government Agencies, NUC, JAMB, TETFund, NCC, CVC etc) for University Advancement"],["p","9. Creating University Strategic Businesses Units/Commercial Ventures and Consultancy Services for improved Fund Generation"],["p","10. Improving Institutional Governance and Financial Management Systems as well as University Internal Control Mechanisms for Sustainable Growth."],["p","11. Improving Human Resource Development and Management for Greater Efficiency and Overall University Development."],["p","STRATEGIC PLAN"],["p","My overall vision will be to provide academic, professional and vocational training of high quality, ensuring their integrity and reputation and producing graduates who will compete with their peers in any part of the world. To give effect to this vision, we will develop a Strategic Plan for the University that will provide a rational, comprehensive and holistic guide to the growth and development of the University within a five (5) year period. This will be premised on identification and prioritization of our needs, mobilization of human and financial resources to attend to these needs within the specified time-frame."],["p","In particular, we shall mobilize resources in the area of academic development to ensure that all existing and future programmes in the University receive full accreditation as and when due both by the National Universities Commission (NUC) and different Professional Regulatory bodies."],["p","SUPPORT OF STAKEHOLDERS"],["p","As we all know, the human factor is the most critical in the attainment of any developmental effort. Accordingly, to drive our vision of accelerating our progress to be an institution of global repute, we will on a continuous basis engage, train, re-train and motivate our human resource both staff and students to achieve desired results. Each of us must be purposeful, focussed, committed, pro-active, resourceful and have result-oriented mindset. It is important to note that we shall appreciate and reward results and not efforts. On our part as Management, we shall ensure that staff and students welfare are given top priority."],["p","At this juncture, i must state that the achievement of our set objectives for sustainable development of our University cannot be realized without mutual trust, peace and stability. I sincerely appeal to everyone, staff, students, traditional rulers and members of the host communities and other stakeholders to create the conducive atmosphere for teaching, learning and community service. We must allow God to lead us in oneness of purpose, in a spirit of love, friendship and fraternity, unity and mutual co-existence as we conduct the business of grooming the next generation of leaders for their families, our dear State Imo, our country Nigeria and for the global community. This is simply my mission as Vice-Chancellor."],["p","COVID-19 SITUATION"],["p","I must emphasize that COVID-19 has left its devastating impact on the global economy including the education system. As we plan to introduce measures for safe education for our students in the future as well as safety of our staff, we must at the present observe all established COVID-19 protocol including mandatory mask policy, hand hygiene, use of sanitizers, social distancing, vaccination etc. Unlike the first and second waves of infection, the on-going third wave of infection by the Delta variant is stealthily having a devastating toll on our population, killing many people and spreading widely. We must remain vigilant and take all necessary precautions."],["p","HISTORY IN PERSPECTIVES"],["p","History in its fair sense recognizes that KO Mbadiwe University as a new institution of learning took root from the defunct Eastern Palm University which was established in 2016. To the glory of God and the lasting ingenuity of her founding Fathers, we inherited staff and students and above all met very good infrastructure as well as processes and extant and cherished traditions of a university. Hence, the environment is already fertile for greater exploits. Therefore, credit must be given to everyone who played a role in the establishment and management of the defunct Eastern Palm University, particularly His Excellency Owelle Rochas Okorocha, the former Governor of Imo State and Visitor to Eastern Palm University. Thus, without equivocation, I must say that aided by the grace of God and our dedication to duty, we are committed to upgrading this history met on ground to an enviable height, hence, leaving a culture far better than we met it."],["p","CONCLUSION"],["p","Finally, I am confident that with your total commitment and loyalty and absolute trust and abiding faith in God Almighty our merciful father, we shall succeed in the transformation of Kingsley Ozumba Mbadiwe University to world-class status. For in the words of the Psalmist in Chapter 127 verse 1, “if the Lord does not build the house, the work of the builder is useless”."],["p","Thank you and May God bless us all."],["p","Professor Ikechukwu Nosike Simplicius Dozie KSM, JP"],["p","BSc; MSc (Nigeria); PhD (Jos);"],["p","FPPSN; FNSM, FAIPH, FPCEHSN; ASIF; FSEPHON"],["p","Vice-Chancellor"]]},{"id":9,"cat":"Campus","date":"2021-10-01","title":"Uzodimma assures govt MDAs of support, donates buses to them","by":"","img":null,"sum":"Governor Hope Uzodimma of Imo State has assured ministries, departments and agencies of government of his readiness to support them discharge their duties effectively.The governor gave the assurance Monday while…","body":[["p","GOVERNMENT OF IMO STATE"],["p","PRESS RELEASE"],["p","Governor Hope Uzodimma of Imo State has assured ministries, departments and agencies of government of his readiness to support them discharge their duties effectively.The governor gave the assurance Monday while flagging-off the distribution of 19 Toyota Hiace Buses to Ministries, Departments and Agencies in Imo State to enhance the performance and activities of their personnel."],["p","Governor Uzodimma said the vehicles are meant to appreciate those establishments that are really working hard and to encourage them to do more in terms of performance and productivity."],["p","The Governor said the vehicles are fitted with tracking-system devices of world class standard and speed-limits that will help check the excesses of reckless drivers. He promised to continue to encourage other sectors of the government that are doing well, saying his government \"has come to serve the people through encouragement and motivation.\""],["p","Appreciating the Governor’s gesture on behalf of the beneficiaries, the Vice Chancellor of K. O. Mbadiwe University, Prof Ikechukwu Dozie thanked Governor Uzodimma for his benevolence and encouragement which he said will motivate them to do more. He promised that the recipients will put the vehicles to proper use as well as take proper care of them to ensure that they serve the purpose for which they were given."],["p","Prof. Dozie also prayed God to continue to sustain the Governor and all those working with him so that they will continue in their efforts towards delivering the dividend of democracy to Imo people."],["p","Some of the MDAs that got the vehicles include: University of Agriculture and Environmental Sciences Umuagwo, Civil Service Commission, Imo State Independent Electoral Service Commission, the Judiciary, and Customary Court of Appeal. Others are Local Government Service Commission, Secondary Education Management Board, the Office of the Secretary to Government of Imo, Ministry of Women Affairs and Vulnerable Groups among others."],["p","The Deputy Governor of Imo State, Prof. Placid Njoku, Secretary to the Government of Imo State, Chief Cosmas Iwu, Chief of Staff, Barr. Nnamdi Anyaehie, the Principal Secretary to the Governor, Dr. (Mrs.) Irene Chima, and other members of the Executive Council witnessed the presentation which held at the Government House premises."],["p","Oguwike Nwachuku"],["p","Chief Press Secretary and Media Adviser to the Governor"],["p","September 28, 2021."]]},{"id":8,"cat":"Leadership","date":"2021-09-21","title":"Familiarisation Visit to Traditional Rulers","by":"Obinna I Anyanwu","img":null,"sum":"To the awesome glory of God Almighty and with deep sense of humility and a committed and patriotic sense of responsibility, I am happy to be in your midst today to seek audience and familiarize with you all as…","body":[["p","AN ADDRESS BY THE VICE-CHANCELLOR, KINGSLEY OZUMBA (KO) MBADIWE UNIVERSITY OGBOKO, PROFESSOR IKECHUKWU NOSIKE SIMPLICIUS DOZIE ON THE FAMILIARISATION VISIT TO TRADITIONAL RULERS OF UMUMA-EBENMANO CLAN, IDEATO SOUTH LGA ON JULY 19, 2021."],["p","Your Royal Highnesses,"],["p","Principal Officers of the University,"],["p","Distinguished Ladies and Gentlemen."],["p","To the awesome glory of God Almighty and with deep sense of humility and a committed and patriotic sense of responsibility, I am happy to be in your midst today to seek audience and familiarize with you all as traditional rulers and custodians of the culture and traditions of the Umuma-Ebenmano clan in Ideato South LGA, Imo State, Nigeria. This I do by the special grace of God in my capacity as the Vice-chancellor of Kingsley Ozumba (KO) Mbadiwe University (KOMU), Ogboko Ideato South LGA Imo State."],["p","As Your Royal Highnesses know, the purpose of a university is to create knowledge through scholarship and research; transmit knowledge through instruction (i.e.teaching) and lastly; apply knowledge through public service. In other words, universities are created to satisfy specific or general educational needs of a nation through teaching of students, conduct of research and dissemination of knowledge together with other community activities. Therefore, the primary mission of the university is simply, teaching, research and community service."],["p","History now recognises the fact that the Kingsley Ozumba Mbadiwe University was established through the Enactment of the Kingsley Ozumba (KO) Mbadiwe University (Establishment) Law No. 1 of 2021, Imo State of Nigeria by His Excellency, Senator Hope Uzodimma on 18th February, 2021. This Law repealed the Eastern Palm University (Establishment) Law No. 3 of 2019. The Law also established the Kingsley Ozumba (KO) Mbadiwe University as a multi-campus university with the main Campus at Ogboko in Ideato South Local Government Area of Imo State. Thus, Kingsley Ozumba Mbadiwe University becomes the 42nd State University and the 143rd University in the Nigerian University System and as well, the 2nd Imo State-owned university."],["p","The mandate of KOMU is, \"to encourage the advancement of learning in Imo State in particular and Nigeria in general, to hold out to all persons without the distinction of race, creed or sex and to give them the opportunity of acquiring higher education in various fields of study\"."],["p","To translate this vision into reality, our dear Governor, His Excellency Senator Hope Uzodimma and Visitor to the Kingsley Ozumba Mbadiwe University appointed me Vice-chancellor. I am deeply grateful to the Governor for finding me worthy to serve in this capacity as the Vice-chancellor. I promise to lead KOMU to be a renowned institution for the pursuit of learning and scholarship as envisioned by the Governor and to the benefit of humanity and the glory of God."],["p","My overall vision for KOMU as enshrined in the Law of Establishment is to provide academic, professional and vocational training of high quality, ensuring their integrity and reputation and producing graduates who will compete with their peers in any part of the world. Our core values to drive our vision for the actualization of our mission will be anchored on integrity, excellence, team work, innovation and collaboration."],["p","For us to succeed in the task of building KOMU to be an institution of repute and reckoning and a first choice destination for teeming youths seeking world-class education and qualitative mentorship, we need the support of Government and various critical stakeholders, especially the traditional rulers and host communities."],["p","We cannot gain say the fact that as traditional rulers and custodians of the culture of the land, Umuma-Ebenmano Clan, Ideato South LGA, you are not just stakeholders but very important ones, critical to the achievement of our goal of building a world-class university of deep pride and service to our people and the rest of humanity. Your Royal Highnesses, this is my mission today on this familiarisation visit to seek your wise counsel, seek peace of the land and most importantly seek your blessings as we begin this delightful but challenging task."],["p","We must understand that my task as the Vice-chancellor and a public servant leader is simply to lead the efforts towards providing qualitative education and mentorship to the young men and women who seek KOMU as an institution of choice and train them for self-actualization and to contribute to the common good in society."],["p","As members of our host communities, we appreciate your enormous sacrifices and contributions towards the establishment of this University. Similarly, we thank the former Governor of Imo state, His Excellency Owelle Rochas Okorocha, OON and Visitor to the Eastern Palm University for his vision and positive contributions. Accordingly as Management, we assure you all that we will do our best in deep appreciation of your support and sacrifice through our various Institutional Corporate Responsibilities."],["p","Finally, I am confident that with your firm support, KOMU by the grace of God will be a win-win for everybody in the delivery of her mandate."],["p","Once more, I thank Your Royal Highnesses for finding time from your various busy schedules to be part of this interaction. Thank you for your kind attention. May God bless us all."],["p","Professor Ikechukwu Nosike Simplicius Dozie ."],["p","BSc; MSc (Nigeria); PhD (Jos); FPPSN; FPCEHSN; ASIF; FSEPHON"],["p","VICE-CHANCELLOR KOMU"]]},{"id":1,"cat":"Partnerships","date":"2021-09-18","title":"Dr. Ihebuzor Donates Books To The University","by":"Obinna I Anyanwu","img":null,"sum":"Dr Reginald Ihebuzor, a Development Expert, writer and the Coordinating Consultant, Niger Delta Development Bank Project has donated for different academic disciplines, ranging from medicine, politics, economy, science…","body":[["p","Dr Reginald Ihebuzor, a Development Expert, writer and the Coordinating Consultant, Niger Delta Development Bank Project has donated for different academic disciplines, ranging from medicine, politics, economy, science books, inspirational books among others to Kingsley Ozumba Mbadiwe University Ogboko, (KOMU), Imo state, University of Agriculture and Environnmental Sciences ,Umuagwu, Imo State and others schools in memory of his wife, late Dr Nnenna Nkeiruka Ihebuzor, a Consultant Pediatrician and a celebrated public servant."],["p","Dr Ihebuzor in his address at the occasion appreciated the unique leadership qualities of the Vice Chancellors Prof N.S Dozie and Professor Patrick. E. Egbule, of University of Agriculture and Environmental Sciences, Umuagwo, both of whom he said are his close friends , adding that their appointments will bring about rapid developments in the schools, especially at this cradle stage.He also described the duo as builders that are deep rooted and highly knowledgeable in school management. He expressed his family’s great love for books and the inepth knowledge they have acquired from books. According to him, his son Chima Ihebuzor wrote hundred poems in two months titled ” The Power of Dreams”, a Century of Poems which were inspired by his late mother in whose honour the books were donated to the institution. With a solemn expression, he described his late wife as his jewel of inestimable value, an unusual woman with great wit and motivation. ”The death of a good spouse is what I don’t wish even my enemy."],["p","My late wife was the secret of my numerous achievements. She was a great wife, mother, teacher and a lover of books. As a voracious reader, she invested in books. A Foundation has been established in her honour”, he stated Prof Ikechukwu N. S. Dozie, the Vice Chancellor of K.O. Mbadiwe University with a heart of gratitude to the family accepted the pile of books donated to the school and described the gesture as a great gift to humanity and a milestone achievement. ”Books are resource materials for knowledge and soul nourishment. We share in your passion in donating books in memory of your beloved wife”, he expressed. He further appreciated the family for being the first benefactor of the school and helping them in their humble beginning. According to the erudite professor, education is the responsibility of everyone and should not be abandoned for the government and the school alone. He urged successful Imolites to contribute their quota to the growth and development of the school while assuring them that K. O Mbadiwe University will become the best university in the country in no distant time."]]},{"id":2,"cat":"Admissions","date":"2021-09-07","title":"PUBLIC NOTICE: Commencement Of 2021/2022 Academic Session","by":"Obinna I Anyanwu","img":null,"sum":"The Management of Kingsley Ozumba (KO) Mbadiwe University, Imo State Nigeria has cancelled the 2020/21 academic session. The cancellation was due to issues related to the COVID-19 Pandemic which affected the timely…","body":[["p","PUBLIC NOTICE"],["p","KINGSLEY OZUMBA (KO) MBADIWE UNIVERSITY OGBOKO, IMO STATE CANCELS THE 2020/2021 ACADEMIC SESSION AND COMMENCES THE 2021/2022 ACADEMIC SESSION ON SEPTEMBER 27, 2021"],["p","The Management of Kingsley Ozumba (KO) Mbadiwe University, Imo State Nigeria has cancelled the 2020/21 academic session. The cancellation was due to issues related to the COVID-19 Pandemic which affected the timely completion of the 2019/2020 academic session and its consequent spillover effects on the commencement and successful conclusion of the 2020/2021 Session."],["p","Academic activities which were suspended due to the transition from the erstwhile Eastern Palm University to KO Mbadiwe University will now recommence in the 2021/2022 session."],["p","Old students are expected to return to Campus on Tuesday October 5, 2021 as several interventions on the University Campus environment and rehabilitation of many deteriorating physical facilities will have been completed. Admissions of new students will commence on September 30, 2021 as approved by the JAMB Policy meeting of August 31, 2021."],["p","Staff and Students will be required to observe strictly all COVID-19 protocol. In this respect, staff and students are expected to return with adequate face masks, face shields and hand sanitizers. Management will ensure provision of adequate water stations to encourage hand hygiene as well as social (physical) distancing in all University activities."],["p","Management assures the Government and good people of Imo State and indeed all Nigerians of her deep commitment to grow KO Mbadiwe University to be a World-Class University and consequently solicits the support of all stakeholders to achieve her overriding objective of training our children for self-actualization and for the task of nation building."],["p","Signed,"],["p","Management"]]}];
